    let mut score = post_residual as f64;

    // 1. Exact fit reward: Strongest signal for completion
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2. Harmonic Class Logic: Prefer filling bins to specific thresholds based on item size
    // We penalize 'orphaned' space that is too small for common item sizes (10-30)
    if post_residual > 0 && post_residual < 20 {
        score += 40.0;
    }

    // 3. Next-Item Lookahead: If the next item fits into the current post_residual, incentivize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 150.0;
        // Further reward if it creates a near-perfect fit for the lookahead item
        if (post_residual - next_item_size) < 10 {
            score -= 100.0;
        }
    }

    // 4. New Bin Thresholding: Prevent opening new bins unless the current options are very poor.
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if fitting_bins_count is low
        if open_bins_count > 0 {
            score += 250.0; // Heavy penalty for opening new bins
        }
        // If it's the very last item, opening a new bin is mandatory, so neutralize
        if step_index == total_items - 1 {
            score -= 1000.0;
        }
    }

    // 5. Global state normalization: Prefer filling bins that are already partially full
    // compared to bins that are nearly empty to keep the number of active bins low.
    let utilization = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += (1.0 - utilization) * 20.0;

    // 6. Avoid "Dead Zone": If post_residual is in a range that is hard to fill (e.g., 1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalize creating tiny slivers of space (1-9) that are hard to fill later
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - (post_residual as f64 * 4.5);
    }

    // Heuristic: If we have a lookahead item, prioritize bins that leave space for it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that perfectly accommodate the next item (synergy)
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize bins that block the next item from fitting here if it could have
            score += 15.0;
        }
    }

    // Dynamic threshold: As we approach the end of the stream, prioritize packing tightly
    // over keeping bins open for future flexibility
    let tightness_weight = 20.0 * progress;
    score += tightness_weight * (mean_residual - post_residual as f64);

    // If this is the only bin that fits the item, make it highly attractive to avoid 
    // opening a new bin unnecessarily (unless the fit is truly catastrophic)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // If considering a new bin, penalize it relative to the average state of current bins
    if bin_residual == bin_capacity {
        score += 20.0 + (mean_residual * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Basic Best-Fit strategy: prioritize minimizing post_residual (the leftover space).
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin prematurely unless the current fit is terrible.
    // If this is a new bin (bin_residual == bin_capacity), set a threshold cost.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, but reduce penalty if we have many open bins already
        // or if the current item is very large and unlikely to pair well with existing residuals.
        score = 45.0 - (open_bins_count as f64 * 0.5);
    } else {
        // 2. Lookahead matching: If the next item fits into the post_residual, 
        // we reward this placement significantly to create "perfect pairs".
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        }

        // 3. Penalty for "fragmentation": If the post_residual is small but not zero,
        // it is often worse than a slightly larger residual because it becomes unusable.
        // We add a penalty for residuals in the range [1, 9].
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // 4. Global balance: If the current bin's residual is significantly below the mean 
        // residual of other bins, we penalize it to encourage filling bins to a similar level.
        if (post_residual as f64) < mean_residual {
            score += (mean_residual - post_residual as f64) * 0.2;
        }
    }

    // 5. Final adjustment: If this is the only bin that can fit the item, 
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score is the remaining space (Best Fit strategy)
    let mut score = post;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize values below 10 (hard to fit anything useful) non-linearly.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powf(2.0) * 5.0;
    }

    // Lookahead logic: if the next item is large, favor bins that retain enough space for it.
    if next_item_size > 0 {
        let n_item = next_item_size as f64;
        if post < n_item {
            // Severe penalty if this bin becomes unusable for the next item
            score += (n_item - post) * 2.5;
        }
    }

    // Dynamic thresholding based on stream progress: 
    // As we reach the end of the stream, we become more aggressive in consolidating bins (Best Fit).
    // Earlier in the stream, we are more tolerant of slightly larger residuals to keep options open.
    let consolidation_pressure = progress.powf(0.5) * 10.0;
    score += (post / capacity) * consolidation_pressure;

    // If this is a new bin (bin_residual == bin_capacity), calculate an entry cost.
    // We only open a new bin if the current fit quality is extremely poor compared to the mean.
    if bin_residual == bin_capacity {
        // High barrier to entry: only open if existing bins are very crowded (mean_residual low).
        score = 25.0 + (mean_residual * 0.5) - (progress * 5.0);
    } else {
        // Favor bins that are already closer to the mean residual to maintain uniform bin usage.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
