    score += (progress * 20.0) * (post / bin_capacity as f64);

    // If this is the only bin that can fit the item, we are forced to use it.
    // Lower the score to ensure it is picked over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
