        // If we have many open bins, we are already fragmented; be more willing to open a new one.
        score -= (open_bins_count as f64) * 1.5;
    }

    // 4. Mean Residual Balancing: If this bin's residual is significantly better than the mean,
    // favor it to keep the average bin usage consistent.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Last Chance Heuristic: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
