pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small for common items, but too large to be efficient)
    // We target a residual that allows the next item to fit perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact matches or near-perfect fits (Best-Fit principle)
            score -= (bin_capacity - post_residual) as f64 * 0.5;
            score -= (post_residual - next_item_size) as f64 * 2.0;
        } else {
            // Penalize if the current placement prevents the next item from fitting
            score += (next_item_size - post_residual) as f64 * 5.0;
        }
    }

    // 2. Control opening new bins
    // If this is a new bin (bin_residual == bin_capacity), penalize based on current fragmentation
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already very tight
        // or if we have very few fitting options.
        if mean_residual > 20.0 && fitting_bins_count > 0 {
            score += 100.0;
        } else {
            score += 10.0;
        }
    }

    // 3. Prefer bins that keep the mean residual balanced
    // If post_residual is close to the mean_residual, it keeps bins homogeneous
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 4. Progress-based scaling
    // As we approach the end of the stream, prioritize packing tighter (Best-Fit)
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // post_residual: 0 means a perfect fit.
    // We want to pack tightly, avoiding small fragments (dead space) that cannot fit common items.

    let mut score = post_residual as f64;

    // 1. Penalize "near-misses" (creating small unusable fragments). 
    // If post_residual is < 10 (the minimum item size), it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead: If next_item_size is large, prioritize bins that can accommodate it.
    // If post_residual < next_item_size, we punish the current choice because it blocks the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // 3. Global state: If we have many open bins, prioritize filling existing ones.
    // If we have very few, we are more flexible.
    score += (open_bins_count as f64) * 0.5;

    // 4. Dynamic time horizon: As we approach the end of the stream, be more conservative.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.2;
    }

    // 5. If this is a new bin (bin_residual == bin_capacity), make it expensive 
    // unless the fit in existing bins is terrible.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, reduced by the number of existing bins.
        score = 85.0 + (open_bins_count as f64 * 0.1);
    } else {
        // If this is the last chance for an item to fit in an open bin, make it attractive.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 6. Prefer bins that keep the mean_residual of the system balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (very small residuals that likely won't fit future items)
    // Small residuals like 1-9 are often worse than empty bins for large items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    }

    // 2. Lookahead optimization: If next item is large, favor larger post_residuals.
    // If next_item_size is 0, we are near the end of the stream; prioritize packing tightly.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            score -= 10.0;
        }
    }

    // 3. Global state awareness: If we have many open bins, prioritize filling existing ones.
    // If we have few, prioritize keeping space open for future variability.
    score += (open_bins_count as f64 * 2.0) * (1.0 - progress);

    // 4. Dynamic thresholding for new bins:
    // Only open a new bin if the current fit is extremely inefficient (post_residual > 30).
    if bin_residual == bin_capacity {
        if post_residual > 30 {
            score = 15.0; // Competitive score to trigger new bin creation
        } else {
            score = 1000.0; // High penalty for opening new bin unnecessarily
        }
    }

    // 5. Favor bins that bring the residual closer to the global mean (balancing load).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items)
    // Residuals between 1 and 9 are statistically likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: Reward bins where the post_residual can accommodate the next item.
    // If post_residual is perfectly sized for the next item, we create a tighter packing.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            // Penalize if we are blocking the next item from fitting in this bin
            score += 15.0;
        }
    }

    // 3. Global state adaptation:
    // If we have many open bins, we should be more selective (Best-Fit tendency).
    // If we have few open bins, we should be more forgiving.
    score += (open_bins_count as f64) * 0.5;

    // 4. Fitting constraints:
    // If this is the only bin that can fit the item, prioritize it to avoid opening a new bin
    // prematurely, unless the new bin is significantly better (e.g., perfect fit).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. New bin handling:
    // Only open a new bin if the current fit is very poor (large post_residual).
    if bin_residual == bin_capacity {
        // Only open new if we can't find a tight fit elsewhere (base score is 100)
        score = 85.0 + (mean_residual * 0.2);
    }

    // 6. Prefer filling bins that are already closer to capacity (Best-Fit)
    score += (bin_capacity - bin_residual) as f64 * 0.1;

