}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score is the residual space; we want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead zones": if the post_residual is too small to fit 
    // likely future items (modeled by 10), penalize it non-linearly.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 2.0;
    }

    // Lookahead coupling: if the next item is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next item, apply a penalty.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post).powf(1.5);
    }

    // Stream progression adjustment:
    // Early in the stream, be more aggressive with packing (Best Fit).
    // Late in the stream, be more cautious about opening new bins.
    if fitting_bins_count == 0 {
        // This is the new-bin candidate. Penalize it based on progress.
        // Opening a new bin is expensive, but becomes necessary as we approach the end.
        score += (1.0 - progress) * (capacity * 0.5);
    } else {
        // This is an existing bin. Reward it if it balances the mean residual.
        // We want to keep residuals low to minimize wasted space.
        score += (post - mean_residual).abs() * progress;
    }

    // Non-linear interaction: penalize high open_bins_count as we progress.
    score += (open_bins_count as f64) * progress * 5.0;

    score
}

