            score -= (100.0 - lookahead_fit as f64) * 0.5;
        } else {
            // Penalize if this placement prevents the next item from fitting (if it could have fit elsewhere).
            score += 20.0;
        }
    }

    // 3. Density Balancing: If we have many open bins, prioritize filling the ones with the lowest residuals
    // (Best-Fit principle). If we have few bins, prioritize keeping the mean residual high to allow flexibility.
    let density_factor = (open_bins_count as f64) / (1.0 + mean_residual);
    score += density_factor * 5.0;

    // 4. Thresholding: If this is the last fitting bin, we are forced to take it or open a new one.
