    // 4. Density Balancing: Prefer bins closer to the global mean residual to keep bins uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. New Bin Logic: If bin_residual == capacity, we are evaluating opening a new bin.
    // Only do this if we are forced to (fitting_bins_count == 0) or if all other fits are disastrous.
    if bin_residual == bin_capacity {
