    if progress > 0.8 {
        score -= (1.0 - progress) * 50.0;
    }

    // 6. Fitting Constraint: If this is the only bin that can fit the item,
    // lower the score to ensure we don't accidentally open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
