    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    }

    // 2. Best-Fit logic: prioritize bins that leave the smallest post_residual
    // We already start with post_residual, so we refine it.

    // 3. Lookahead Matching: 
    // If post_residual is close to next_item_size, we reward it (Best-Fit-Decreasing logic)
    // If next_item_size is 0, we focus on minimizing absolute waste.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward placements that leave exactly enough room for the next item
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.3;
        } else {
            // Penalize placements that make the next item impossible to fit
            score += 20.0;
        }
    }

    // 4. Density Balancing:
    // If we have many open bins, penalize creating more by favoring bins that are already "fuller"
    // (bins with smaller residuals).
    score += (open_bins_count as f64) * 0.2;

    // 5. Thresholding:
    // If this is the last chance to fit the item in an existing bin, favor it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Global efficiency:
    // As the stream progresses, become more conservative about opening new bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize creating "fragmented" space (small residues that are hard to fill)
    // We prefer residues that are 0 (perfect fit) or >= 20 (likely to fit future items).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // 2. Lookahead mechanism: If next_item_size fits in post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
