    // 4. Scarcity heuristic: If this is the only bin that fits, prioritize it heavily to avoid new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 5. Global state normalization: penalize deviations from the mean residual to keep bin fill-levels uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
