    }

    // 3. Lookahead: If the next item exists, penalize bins that leave a residual 
    // too small to accommodate the future item, as this forces further fragmentation.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0;
        }
    }

    // 4. Global pressure: As we approach the end of the stream, prioritize closing bins
    // by penalizing open_bins_count more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress * 2.0);

    // 5. Prefer tight fits (Best Fit heuristic)
    // We reward the bin that results in the smallest post_residual.
    // The base score starts with post_residual, which inherently favors Best Fit.
    // We adjust it based on the mean_residual to prevent over-packing one bin 
    // at the expense of others.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Final safety: If only one bin can fit the item, strongly prefer it 
    // to avoid the penalty of opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that result in smaller residuals
    // (Already handled by score = post_residual)

    // 2. Penalty for creating "dead space" that is too small for any future item.
    // If post_residual is < 10 (smallest possible item), it's effectively wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Matching: If the next item fits perfectly into the post_residual, 
    // prioritize this bin highly to consolidate space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // If the next item fits, reduce penalty slightly
            score -= 10.0;
        } else {
            // If next item does not fit, it's a slightly worse choice
            score += 5.0;
        }
    }

    // 4. Global balance: If we have many open bins, prioritize filling current ones 
    // over opening new ones. If this is a new bin (residual == capacity), add a heavy penalty.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Mean residual alignment: Avoid bins that deviate significantly from the mean 
    // residual to keep packing density uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 6. Urgency: If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for creating "dead space": residuals too small for any future item
    // If post_residual is < 10 (smallest item size), it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // 2. Lookahead optimization: 
    // If the next item fits into the current post_residual, we reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Global state balancing:
    // If many bins are open, try to pack tighter (Best Fit behavior).
    // If few bins are open, allow more flexibility to avoid future fragmentation.
    if fitting_bins_count > 0 {
        let tightness_penalty = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += tightness_penalty;
    }

    // 4. New bin management:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless the item is large or we are late in the stream.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 45.0;

        // If the item is large, reduce the penalty because it needs a fresh start
        if item_size > 60 {
            score -= 25.0;
        }

        // Near the end of the stream, prioritize closing existing bins over opening new ones
        score += progress * 30.0;
    }

    // 5. Fragmentation avoidance:
    // If the post_residual is close to the mean_residual of other bins, 
    // it suggests we are creating a uniform waste profile, which is usually bad.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score is the residual space; we want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead zones": if the post_residual is too small to fit 
    // likely future items (modeled by 10), penalize it non-linearly.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 2.0;
    }

    // Lookahead coupling: if the next item is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next item, apply a penalty.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post).powf(1.5);
    }

    // Stream progression adjustment:
    // Early in the stream, be more aggressive with packing (Best Fit).
    // Late in the stream, be more cautious about opening new bins.
    if fitting_bins_count == 0 {
        // This is the new-bin candidate. Penalize it based on progress.
        // Opening a new bin is expensive, but becomes necessary as we approach the end.
        score += (1.0 - progress) * (capacity * 0.5);
    } else {
        // This is an existing bin. Reward it if it balances the mean residual.
        // We want to keep residuals low to minimize wasted space.
        score += (post - mean_residual).abs() * progress;
    }

    // Non-linear interaction: penalize high open_bins_count as we progress.
    score += (open_bins_count as f64) * progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
