pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (tighter packing)
    // 2. Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is < 10, it is likely unusable. Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead Logic: If we have a next_item, prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit both current and next item
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Penalize bins that "block" the next item from fitting
            score += 15.0;
        }
    }

    // 4. Harmonic Classes: Attempt to align residual with common item sizes (e.g., multiples of 20 or 25)
    // This helps keep bins "compatible" for later items.
    let harmonic_alignment = (post_residual % 20) as f64;
    score += harmonic_alignment * 0.5;

    // 5. New Bin Penalty: Heavily penalize opening a new bin unless existing options are terrible.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the mean residual of existing bins is already very tight
            score = 40.0 + (mean_residual * 0.5);
        }
    }

    // 6. Final adjustment for the "last chance" bin to avoid fragmentation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that fall into unusable ranges (1..10)
    // Small gaps are "death traps" for future items (min size is 1).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the current fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless the item itself is very large (e.g., > 70).
    if bin_residual == bin_capacity {
        if item_size < 70 {
            score += 60.0;
        } else {
            score -= 10.0; // Accept large items in new bins to clear space
        }
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // make it highly attractive to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Global Efficiency: If many bins are open, penalize creating more by 
    // increasing the cost of new bins relative to existing ones.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large residual space
    // We want to minimize post_residual, so it stays as the base score.

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, 
    // heavily reward this bin to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New Bin Thresholding: Prevent opening new bins unless the fit is truly terrible.
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // the current fitting options are extremely poor (i.e., they leave very little space).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist
            score += 55.0;
        }
    } else {
        // 4. Mean Residual Balancing: If this bin's post_residual is significantly 
        // better than the average of other open bins, reward it to keep the 
        // "global" waste low.
        if (post_residual as f64) < mean_residual {
            score -= (mean_residual - post_residual as f64) * 0.5;
        }
    }

    // 5. Critical Constraint: If this is the only bin that can fit the item, 
    // force it to be chosen by applying a strong discount.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-residual space (Best Fit objective)
    // We want to minimize this, so smaller post_residual is better.
    let mut score = post_residual as f64;

    // Penalty for creating a new bin: only do it if the fit is truly terrible
    // or if we are nearing the end of the stream and need to consolidate.
    if is_new_bin {
        // High penalty for opening a new bin unless we have very few options
        score += 45.0 - (fitting_bins_count as f64 * 5.0);
        // If we are at the end of the stream, penalize new bins more to force compaction
        score += progress * 30.0;
    } else {
        // Reward bins that keep the mean residual high (keeping bins balanced)
        // or penalize bins that deviate significantly from the mean
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // Lookahead: If next item exists, penalize bins that would make it harder to fit next_item_size
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // This placement makes the bin unable to hold the next item
                score += 15.0;
            } else {
                // This placement leaves space for the next item, reward it
                score -= 8.0;
            }
        }
    }

    // Dynamic threshold: If only 1 bin fits, we are forced to use it; 
    // reduce score to ensure we don't prefer a new bin over this forced fit.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize fragmentation: If post_residual is small but > 0, it's often wasted space
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit principle).
    // Minimize post_residual to keep bins tight.
    let mut score = post_res;

    // Penalty for leaving small "fragmented" gaps (e.g., 1-9) that are hard to fill.
    // As progress increases, we become more sensitive to creating dead space.
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res) * (1.0 + progress * 2.0);
    }

    // Lookahead interaction: If next_item_size fits in the post_residual,
    // strongly favor this bin to maximize bin utilization.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamic thresholding: If this is the only bin that fits the item (fitting_bins_count == 1),
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Global state awareness: If we have many open bins, penalize opening a new one
    // (bin_residual == bin_capacity) to encourage consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 10.0 * (1.0 - progress);
    }

    // Coupling with mean_residual: If current bin is significantly worse than the average,
    // penalize it to force usage of "tighter" bins.
    if post_res > mean_residual {
        score += (post_res - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead" gaps that 
    // cannot accommodate common future items (modulo harmonic logic).
    let mut score = post_residual as f64;

    // Harmonic Penalty: If post_residual is small but > 0, it creates a "sliver" 
    // that is hard to fill. Penalize residuals that don't align well with potential future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Heavy penalty for creating unusable slivers
    }

    // Lookahead Coupling: If next_item_size is large, favor bins that leave enough space for it.
    // If post_residual is smaller than next_item_size, we effectively "waste" the bin for the next step.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // New Bin Thresholding: If we are forced to use a new bin (fitting_bins_count == 0),
    // reduce its score to make it competitive, but scale by current open bin density.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Encourage Best-Fit: Lower score for tighter fits, but reward bins that 
        // keep the mean_residual high to allow future flexibility.
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Progression Weighting: As the stream nears completion, become more aggressive 
    // about closing bins (minimizing residuals regardless of future fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
