        // and how much space is left in them (mean_residual).
        score += 40.0 + (open_bins_count as f64 * 2.0) + (mean_residual * 0.5);

        // If there are other bins that could fit this item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
