        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

    // 5. Critical Last-Chance Logic: If this is the only bin that can fit the item, 
    // make it highly attractive to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
