    let mut score = post_residual as f64;

    // Penalty for opening a new bin: high early on, lower as we approach the end of the stream
    // to allow for better packing density in the final stages.
    if is_new_bin {
        score += (bin_capacity as f64) * (1.0 - 0.5 * progress);
    }

    // Non-linear coupling: penalize bins that result in "sliver" residuals (1-9) 
    // especially when we have many open bins.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 + (open_bins_count as f64 / 10.0));
