    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - progress);
    }

    // Reward bins that bring the mean residual closer to the ideal 
    // (targeting a tighter packing density as we progress).
    let target_residual = 10.0 * (1.0 - progress);
    score += (post_residual as f64 - target_residual).abs() * 0.5;

    // Discourage creating too many open bins if we have a good fit available.
    if fitting_bins_count > 0 && !is_new_bin {
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

