    // We penalize post_residuals that are too small to fit the smallest expected items (10)
    // but large enough to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Favor bins that result in a post_residual that is a multiple of common item sizes
    // This helps pack future items tightly by creating 'harmonic' fit windows.
    if post_residual % 20 == 0 {
