    }

    // Lookahead logic: if next_item_size is large, prefer bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice
    // unless the current choice completes the bin (post_residual == 0).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
