            } else if post_residual < next_item_size && post_residual > 0 {
                // Penalize if current placement blocks the next item from fitting
                score += 25.0;
            }
        }

        // Global State: If many bins are open, prioritize bins that are already 
        // fuller (lower bin_residual) to consolidate space.
        let residual_impact = (bin_residual as f64 - mean_residual) * 0.5;
        score += residual_impact;

        // If this is the only bin that can fit the current item, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    let post = post_residual as f64;

