    let mut score = post;

    // Penalty for opening a new bin: if it's not the only option, make it expensive.
    // As the stream progresses, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
        if fitting_bins_count > 0 {
            score += 100.0 * (1.0 - progress);
        }
    }

    // Lookahead logic: if the next item is large, avoid leaving a small residual that 
    // effectively kills future capacity (e.g., leaving 10-15 space is often "dead").
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post < next_f && post > 0.0 {
