    // Balancing: penalize bins that deviate significantly from the mean residual
    // to encourage uniform fill across all active bins.
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * 0.2;

    // Favor filling bins that are already partially filled (lower mean_residual)
    // versus starting new ones, weighted by progress.
    score += (mean_residual * 0.1) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "fragment" (residual too small to fit common items, but too large to be ignored)
    // We target residuals that leave space for potential next items.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
