    // This helps keep bins packed at similar levels for better future fit.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Urgency: As we approach the end of the stream, prioritize tight fits more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

