        }
    }

    // 5. Global state normalization:
    // If the mean residual is high, we are currently wasting space. 
    // Penalize placements that increase the residual above the current mean.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 6. Progressive tightening:
    // As the stream nears completion, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
