        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // 4. Global state awareness:
        // If this bin is significantly "fuller" than the average, prioritize it (Best Fit variant).
        if (bin_capacity - bin_residual) > (bin_capacity - mean_residual as u32) {
            score -= 5.0;
        }

        // If this is the last chance for this item (only one bin fits), prioritize it to avoid new bins.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
