    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual.
    // This is the baseline, represented by the initial assignment.

    // 2. Penalty for creating "dead space": if the post_residual is too small to fit any likely item,
    // it effectively becomes wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead integration: if the next item fits into the current post_residual, 
    // reward this placement to keep the bin useful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 4. Harmonic thresholding: Favor bins that leave a residual which is a multiple 
    // of common item sizes (e.g., 20, 25, 50).
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // 5. Managing new bin creation:
    // If this is a new bin, apply a threshold penalty to prevent premature opening.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low (bins are full)
        // or if we have no other options.
        if mean_residual > 20.0 && fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score += 30.0;
        }
    }

    // 6. Distribution awareness:
    // As the stream progresses, increase pressure to pack tighter (linear progression).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual ranges that are 
    // too small to fit the smallest possible item (assumed 10) or common item sizes.
    // Residuals < 10 are highly penalized as "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bins Pressure: If fitting_bins_count is 1, this is the last chance.
    // If the post_residual is poor (e.g., > 30), penalize to encourage opening a new bin
    // instead of ruining a potentially good bin, but only if we have few open bins.
    if fitting_bins_count == 1 && post_residual > 30 {
        score += 25.0;
    }

    // 3. Lookahead Integration: If next item fits in the remaining space, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 4. Global Efficiency: Penalize excessive usage of bins relative to mean state.
    // If we are using more bins than average, prioritize filling the tightest gaps.
    if open_bins_count as f64 > (100.0 / (100.0 - mean_residual + 1.0)) {
        score += (post_residual as f64) * 0.5;
    }

    // 5. New Bin Candidate Logic:
    // If bin_residual == bin_capacity, we are evaluating opening a fresh bin.
    // Only choose this if the penalty for fitting into existing bins is high.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is 45.0. 
        // We only open it if existing bins result in "dead space" or poor fits.
        score = 45.0 + (open_bins_count as f64 * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items).
    // If post_residual is < 10, it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead matching: If the post_residual is a near-perfect fit for the next item, reward it.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // If the next item fits perfectly in the current residual, prioritize this bin heavily.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // 3. Density balancing: Encourage keeping the bin residuals close to the mean.
    // This helps prevent "fragmentation" where some bins are nearly full and others are very empty.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.25;

    // 4. Strategic New-Bin Avoidance:
    // If this is the only bin that can fit the item, strongly prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. If this is a new bin (bin_residual == bin_capacity), make it expensive unless necessary.
    // We only want to open a new bin if the existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // As we progress through the stream, if we have many open bins, penalize opening more.
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit style logic)
    let mut score = post_residual as f64;

    // Penalty for creating a "fragment" (space too small for most items, but large enough to waste)
    // We penalize residuals between 1 and 9 (since min item size is often ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if next item exists, favor bins that leave space for it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward bin that can accommodate the next item
        } else if post_residual > 0 {
            score += 15.0; // Penalize bin that blocks the next item
        }
    }

    // Global state weighting: avoid opening new bins unless necessary
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one fits
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no bins fit, normalize the cost of a new bin based on progress
            score = 5.0 + (progress * 10.0);
        }
    } else {
        // Encourage balanced filling: reward bins that stay near the global mean residual
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // Final "tightness" reward: if we are near the end of the stream, prioritize filling to 0
        if progress > 0.8 && post_residual == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual, aiming for the Best-Fit approach (minimizing post_residual).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: increase score proportionally to remaining stream.
    // As we approach the end of the stream, opening new bins becomes increasingly expensive.
    if is_new_bin {
        score += (1.0 - progress) * (bin_capacity as f64 * 0.8);
        // Add a penalty based on how many bins are already open to discourage fragmentation.
        score += (open_bins_count as f64).powf(1.2);
    } else {
        // Reward placements that align with the lookahead item.
        // If the current placement leaves a gap that perfectly fits the next item, reduce score.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap_efficiency = (post_residual - next_item_size) as f64;
            score -= (bin_capacity as f64 - gap_efficiency) * 0.3;
        }

        // Penalty for creating 'dead space' (small residuals that are hard to fill).
        // If post_residual is small but > 0, it's often worse than having 0 residual.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Discourage creating too many open bins if we have many fitting options.
    if fitting_bins_count > 1 && !is_new_bin {
        score -= (fitting_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a "dead zone" (small residuals that are hard to fill, typically < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Reward for perfect or near-perfect fits (Best Fit principle)
    // The lower the post_residual, the better, unless it's zero (perfect).
    if post_residual == 0 {
        score -= 20.0;
    }

    // Harmonic/Modulo logic: prioritize bins where the remaining space is a multiple of common small items
    // This helps aggregate items that complement each other well.
    let harmonic_alignment = (post_residual % 10) as f64;
    score += harmonic_alignment * 0.5;

    // Lookahead logic: If the next item fits into the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Further reward if it creates a near-perfect fit for the next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Penalty for opening a new bin if other bins are available
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0;
    }

    // Scale by stream progression: As we approach the end, prioritize filling existing bins
    // to avoid leaving trailing items in new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 40.0;
    }

    // Penalty for creating a bin with a very large residual that forces future fragmentation
    if post_residual > 60 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small gaps that are unlikely to fit future items (1-9).
    // If post_residual is tiny but > 0, it is often "wasted" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is very tight.
    // If we are considering a new bin (bin_residual == bin_capacity), penalize it based on how many
    // bins are currently open to keep the count low.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    } else {
        // For existing bins, favor those that bring the bin closer to the mean residual of the set.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 4. Criticality Adjustment: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Progression Weighting: As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
