pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prioritize smaller post_residuals (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: Increase as we approach the end of the stream
    // to force consolidation, but keep it low early on to maximize space utilization.
    if is_new_bin {
        score += 25.0 + (progress * 40.0);

        // If we have many open bins already, penalize opening a new one heavily
        score += (open_bins_count as f64) * 2.0;
    }

    // Lookahead logic: If the next item exists, penalize placements that create 
    // a post_residual that is too small to fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This is a "dead space" creator for the next item.
            // If this is the only fitting bin, we have no choice, but otherwise punish it.
            if fitting_bins_count > 1 {
                score += 35.0;
            }
        } else {
            // Reward placements that leave exactly enough space for the next item
            if post_residual < (next_item_size + 10) {
                score -= 10.0;
            }
        }
    }

    // Heuristic: If we are in the later stage of the stream, prioritize 
    // balancing the residuals across bins to avoid stranding small items.
    if progress > 0.7 {
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Final check: If this is the last chance to fit the item in existing bins, 
    // reduce the penalty significantly.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation exponentially as we approach the end of the stream
    let new_bin_penalty = if is_new_bin {
        (1.0 + progress.powi(2)) * 50.0
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: minimize post_residual, but normalize by capacity
    // Penalize large post_residual (wasted space)
    let waste_score = post_residual as f64;

    // Lookahead logic: if next_item_size is large, avoid leaving a residual 
    // that is just slightly too small to fit the next item.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        // If the current placement makes the next item impossible to fit, add a penalty
        // proportional to the size of the next item (to force larger bins open earlier)
        (next_item_size as f64) * 0.5
    } else {
        0.0
    };

    // Interaction term: If few bins can fit the current item, prioritize keeping them open
    // to avoid fragmenting the bin space.
    let scarcity_factor = if fitting_bins_count == 1 && !is_new_bin {
        -20.0 
    } else {
        0.0
    };

    // Combine terms:
    // 1. waste_score: Minimize remaining space (Best Fit)
    // 2. new_bin_penalty: Discourage opening new bins late in the stream
    // 3. lookahead_penalty: Discourage creating small gaps that block the next item
    // 4. scarcity_factor: Reward using bins that are 'critical' for the current item
    waste_score + new_bin_penalty + lookahead_penalty + scarcity_factor
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
