    let remainder_mod = post_residual % 25;
    if remainder_mod == 0 {
        score -= 10.0;
    }

    // 4. New Bin Thresholding: 
    // If fitting_bins_count is 1, we are at the last chance. 
    // If we are considering a new bin (bin_residual == bin_capacity), penalize it 
