    // 2. Lookahead optimization: If the next item can fit in the post_residual, 
    // we heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 150.0;
        // Further reward if the post-post residual is near zero (perfect pair fill)
        let post_post_residual = post_residual - next_item_size;
        score -= (100.0 - post_post_residual as f64) * 0.5;
    }

    // 3. Penalty for opening new bins:
    // Only open a new bin if the current fit is extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Heavily penalize opening a new bin unless existing bins are very full.
            score = 80.0 + (mean_residual * 0.5);
        }
    }

    // 4. Scarcity/Pressure: As we approach the end of the stream, prioritize 
    // closing existing bins over creating new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 50.0;
    }

    // 5. Avoid "fragmentation": Penalize bins that leave behind a residual 
    // that is too small for almost any item (e.g., < 10), unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 6. Balance the number of open bins:
    // If we have many open bins, prioritize filling them to reduce fragmentation.
    score += (open_bins_count as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize leaving small gaps that are unlikely to be filled.
    // If post_residual is between 1 and 9, it is highly likely to be dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // reward this placement to increase packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Scarcity/Empty Bin Logic: 
    // If this is a new bin (bin_residual == bin_capacity), only pick it if forced or 
    // if existing bins are too tight to accommodate future potential.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if an existing one can fit the item
            score += 60.0;
        }
        // Increase penalty for opening new bins as we approach the end of the stream
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 4. Global State Balancing:
    // If our average empty space is high, we are being too fragmented. 
    // Favor bins that bring us closer to the mean_residual to keep packing uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Urgency: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalize large dead space (post_residual) exponentially to encourage tightly packed bins
    score += (post_residual as f64).powf(1.5);

    // If it's a new bin, apply a dynamic cost based on stream progression.
    // Early in the stream, we are more willing to open new bins to maintain flexibility.
    // Late in the stream, we penalize new bins heavily to force consolidation.
    if is_new_bin {
        let open_penalty = 15.0 + (progress * 60.0);
        score += open_penalty;
    } else {
        // Favor bins that align with the lookahead item size
        if next_item_size > 0 {
            let space_for_next = post_residual as i32 - next_item_size as i32;
            if space_for_next >= 0 {
                // Reward bins that can accommodate the next item perfectly
                score -= (1.0 / (1.0 + space_for_next as f64)) * 20.0;
            }
        }
    }

    // Penalty for creating a bin with a very small residual that is likely unusable (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // If this is the only bin that fits the item, make it highly attractive to avoid new bin creation
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Global consolidation pressure: if we have many bins open, penalize remaining space more heavily
    score += (open_bins_count as f64) * (mean_residual / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but non-zero, 
    // as they often create "dead space" that cannot fit subsequent items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Coupling: If the next item fits into the current post_residual,
    // strongly incentivize this placement.
