    // penalize it unless no other bin can fit the item or the remaining space 
    // in existing bins is highly fragmented.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0;
        }
