    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive 
    // about packing into existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 100.0;
    }

    // 6. Mean Residual Balancing: If the current bin's post_residual is significantly 
    // lower than the global mean, it's a "tight fit" bin; keep it tight.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
