        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 4. Balance the bin density: Favor bins that stay near the global mean residual.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

