    // while accounting for the next item's potential fit and global bin utilization.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Score: The residual space after placement. 
    // Smaller is better (Best Fit).
    let mut score = post_residual as f64;

    // 2. Penalty for opening a new bin prematurely.
    // If we have other options (fitting_bins_count > 0), penalize the new bin.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 45.0 + (progress * 20.0);
        }
        return score;
    }

    // 3. Lookahead Logic: 
    // If the next item fits into this post_residual, reward the bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0; 
        // Strongly reward if the post_residual becomes very small after the next item.
        let post_post = post_residual - next_item_size;
        if post_post < 10 {
            score -= 15.0;
        }
    }

    // 4. Global State Balancing:
    // If our current bin is much emptier than the average, we are wasting space.
    // Penalize bins that are "too empty" compared to the global mean.
    if (bin_residual as f64) > mean_residual * 1.2 {
