}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core heuristic is based on the Best-Fit principle, but adjusted for the 
    // "last chance" scenario and stream progression to manage bin density over time.

    // Penalty for creating a "small" residual that is unlikely to fit future items.
    // We define a "bad" residual as one smaller than the minimum possible item size (10).
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Reward bins that are nearing capacity as we approach the end of the stream.
    let closure_reward = (1.0 - progress) * (bin_capacity as f64 - post).powf(1.5) * 0.1;

    // Lookahead: if the next item can fit in the current post_residual, prioritize this bin.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64)
    } else {
        0.0
    };

    // If fitting_bins_count is 1, it's the only bin that can take this item.
    // If it's a new bin (bin_residual == bin_capacity), we heavily penalize it 
    // unless the fragmentation penalty of others is massive.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 { 0.0 } else { 45.0 + (progress * 20.0) }
    } else {
        0.0
    };

    // Combine factors:
    // Base score is post_residual (Best-Fit logic).
    let mut score = post + fragmentation_penalty + new_bin_penalty + lookahead_bonus - closure_reward;

    // Apply a slight dampening based on open_bins_count to prevent excessive spreading.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
