    // fit is significantly better than existing options (e.g., creating a near-perfect bin).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (50.0 * (1.0 - progress)) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Coupling: favor bins that keep the mean_residual of open bins balanced.
    // If post is lower than mean, we are "tightening" the bin, which is good.
    let balance_factor = (post - mean_residual).max(0.0) * 0.5;

    let mut score = post + fragmentation_penalty + lookahead_penalty + new_bin_penalty + balance_factor;

    // If this is the last chance to fit an item in an existing bin, reduce penalty significantly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
