            // Apply a heavy penalty for opening a new bin if other bins exist
            score += 45.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 3. Lookahead Sensitivity: Reward placements that leave a residual 
        // capable of fitting the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }

        // 4. Fitting Constraint: If this is the only bin that fits, prioritize it 
        // to avoid fragmentation, but only if the fit isn't extremely poor.
        if fitting_bins_count == 1 && post_residual > 5 {
            score -= 15.0;
        }
    }

    // 5. Global Balance: Penalize bins that deviate significantly from the mean residual
    // to keep bin utilization uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize leaving 
    // small slivers (e.g., 1-9) that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Coupling: If next_item_size fits in the post_residual, 
    // prioritize this bin to maximize bin utilization.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New Bin Thresholding: Discourage opening new bins unless the current 
    // open bins are poor matches for the current item or the average residual is high.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if we have fits available, 
            // unless the current bins are nearly full (mean_residual low).
            score += 120.0 + (mean_residual * 2.0);
        } else {
            // If no fit exists, force opening a new bin by setting score to a baseline.
            score = 10.0;
        }
    }

    // 4. Progress Scaling: As the stream nears the end, become more aggressive 
    // about filling existing bins to avoid stragglers.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.5;

    // 5. Mean Deviation: Favor bins that keep the residual close to the current 
    // global mean to balance load across open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is too sparse to fit potential future items
    // If post_residual is small but > 0, it's often a "dead zone" (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            // Penalize bins that block the next item from fitting
            score += 15.0;
        }
    }

    // If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // If considering a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is high (meaning existing bins are full)
        // or if we are early in the stream.
        if mean_residual > 20.0 && open_bins_count > 0 {
            score += 60.0;
        } else {
            score += 30.0 * (1.0 - progress);
        }
    }

    // Favor filling bins that are already below the global mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "slivers" (very small residuals that are hard to fill).
    // We penalize residuals between 1 and 9 significantly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Dynamic Lookahead Coupling:
    // If we have a next item, penalize bins that cannot fit the next item after this placement.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Global Efficiency Pressure:
    // As the stream progresses, prioritize closing bins (lower mean_residual).
    // If post_residual is significantly better than the current mean, reward it.
    let residual_diff = mean_residual - post;
    score -= residual_diff * progress;

    // New Bin Gatekeeping:
    // Only open a new bin if the current fit is extremely poor (post_residual is very high).
    // We normalize the new bin penalty against progress to allow more flexibility early on.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, but reduce it if we are near the end 
        // to avoid stranding items or if we have many open bins already.
        score = 45.0 + (open_bins_count as f64 * 0.5) - (progress * 10.0);
    }

    // Favor bins that are already "tight" (low residual) to keep the number of open bins minimal.
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (post_residual < 10) as it's often unusable.
    // We heavily penalize small residuals that are too large to be useless, but too small to fit common items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead logic: If the next item fits in the current post_residual, reward this bin.
    // This is a "Best-Fit" refinement using the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Harmonic class alignment: Prefer residuals that are multiples of common item sizes.
    // Items are 1..100; residuals that are 20, 25, 33, 50 are generally more flexible.
    let harmonic_penalty = (post_residual % 20) as f64;
    score += harmonic_penalty * 0.5;

    // 4. New bin management: If this is an empty bin, penalize it based on how many bins are already open.
    // We only want to open a new bin if the current open bins are "too full" to handle the next item.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If we have many fitting bins, opening a new one is almost always bad.
        score += (fitting_bins_count as f64) * 40.0;
    } else {
        // If it's an existing bin, reward it if it's the only one that can fit the item (Last Chance).
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Global state: As the stream progresses, favor tighter packing to avoid tail-end bin waste.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

