    // However, if the bin becomes perfectly full (post_residual == 0), grant a massive bonus.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2. Lookahead optimization (k=2):
    // If the next item fits perfectly into the current post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward small gaps left for the next item (tight packing).
        score -= (100.0 - diff) * 2.5;

        // If the next item fits perfectly, prioritize this bin above all else.
        if diff == 0.0 {
            score -= 1000.0;
        }
    }

    // 3. Penalty for "dead space" creation:
    // If post_residual is small but > 0 and < 10, it's likely unusable.
    if post_residual > 0 && post_residual < 10 {
