    }

    // 5. Mean-residual alignment:
    // Discourage creating bins that deviate significantly from the mean_residual
    // to keep the fill-levels of active bins somewhat consistent.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 6. Progress-dependent scaling:
    // As we approach the end of the stream, prioritize closing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
