    // 4. Global state awareness: if we are early in the stream, favor using existing bins
    // to keep the bin count low, but if we are late, be more aggressive with new bins
    // to finish off the remaining items.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: reduce penalty as we approach the end of the stream.
        score += (80.0 * (1.0 - progress));
    }

    // 5. Fitting count pressure: if this is the only bin that can fit the item, 
    // strongly reward picking it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Mean-residual balancing: avoid bins that are significantly emptier than the average,
    // as these are likely "wasted" bins.
    if (bin_residual as f64) > mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is between 1 and 9, it's likely "unusable" 
    // for future items (min size ~10). Heavily penalize these "sliver" gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If next_item_size is known, penalize residual space 
    // that is too small to fit the next item, forcing a tighter fit for current item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bins pressure: As we progress through the stream, penalize opening 
    // new bins (bin_residual == bin_capacity) if we have existing capacity.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean residual alignment: Reward bins that keep the bin closer to the 
    // global mean residual to balance capacity distribution.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tightly packed.
    // We use a non-linear weight to discourage fragmentation.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead matching: Reward bins where the post_residual can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
