            score += (next_item_size as f64) * 2.0;
        }
    }

    // 3. Mean Residual Balancing: Avoid deviating too far from the average bin utilization.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 4. New Bin Logic: If this is an empty bin, apply a threshold based on the stream progression.
    // We only open a new bin if the current fit is significantly worse than the expected mean.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // As the stream progresses, make it harder to open new bins (penalty increases).
        score += 45.0 + (progress * 30.0);
    } else {
        // If it's the last bin that can fit the item, reward selecting it to avoid waste.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
