    }

    // Best-Fit Decreasing logic: favor tighter fits
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // Lookahead: If next item is large, avoid leaving a residual that cannot accommodate it
    if next_item_size > 0 {
        if post_residual < next_item_size {
