        if bin_residual == bin_capacity {
            score += (open_bins_count as f64 * 5.0) + (mean_residual * 0.5);
        } else {
            // Encourage filling existing bins over opening new ones
            score -= (100.0 - mean_residual) * 0.2;
        }
