pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // Penalize creating small, unusable gaps (1..10)
    let gap_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 - (post_residual as f64 / 10.0))
    } else {
        0.0
    };

    // Lookahead logic: If the next item can fit in the post_residual, prioritize this bin.
    // We reward bins that leave exactly enough room for the next item (synergy).
    let lookahead_score = if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        -15.0 * (1.0 / (1.0 + fit_diff))
    } else {
        0.0
    };

    // Dynamic scaling based on stream progression.
    // Late in the stream, we become more aggressive about filling bins (lowering tolerance for empty space).
    let progress_weight = 1.0 + (progress * 2.0);

    // If this is the only fitting bin, we are forced to use it. 
    // If it's a new bin, we apply a massive penalty unless the current open bins are very full.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if fitting_bins_count == 0 {
            0.0 // Necessary to open
        } else {
            // Penalize opening a new bin if we have fits, scaled by how full the current bins are
            (mean_residual * 0.5) + (20.0 * progress_weight)
        }
    } else {
        0.0
    };

    let score = (post * progress_weight) + gap_penalty + lookahead_score + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
