            score -= (100.0 - (post_residual - next_item_size) as f64).sqrt() * 5.0;
        } else {
            // Penalize placements that make it impossible to fit the next item in this bin
            score += 25.0;
        }
    }

    // 3. Pressure management: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // 4. Global balance: Prefer bins that stay closer to the mean_residual to keep load balanced.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. New bin logic: If this is a new bin (bin_residual == bin_capacity), 
    // only choose it if the penalty for using existing bins is very high.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, reduced by total stream progress
        let progress = step_index as f64 / total_items as f64;
        score += 85.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
