    if post_residual > 0 && post_residual < 10 {
        score += 20.0 - (post_residual as f64);
    }

    // 4. Mean Alignment: If the bin's new residual is significantly higher than the 
    // current mean, it indicates we are creating a "loose" bin. Penalize this.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it 
