    // 3. Open Bins Pressure: Discourage opening new bins unless necessary, 
    // but favor bins that keep the mean_residual high (balanced distribution).
    // If bin_residual == bin_capacity, we are evaluating opening a NEW bin.
    if bin_residual == bin_capacity {
        // Only consider opening a new bin if we have many open bins already or if fitting_bins_count is low
        if open_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // For existing bins, reward placements that leave space for the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Penalize bins that deviate significantly from the mean_residual to keep load balanced
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 4. Final refinement: Favor bins that are "tight" fits (low post_residual)
    // without crossing the dead-space threshold defined above.
    score += post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
