    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 150.0 + (progress * 20.0)
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: reward smaller post_residual (tighter fit)
    // Non-linear coupling: square the post_residual to punish large gaps significantly
    let fit_score = (post * post) / bin_capacity as f64;

    // Lookahead interaction: if next_item_size fits in the post_residual, reward it
    let lookahead_reward = if next_item_size > 0 && post_residual >= next_item_size {
        -25.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64)
