    // favor bins that are already closer to the mean_residual
    let dispersion_penalty = (post_residual as f64 - mean_residual).abs() * 0.1;

    // Final score: minimize this value
    // New bins are penalized, tight fits are rewarded, and lookahead synergy is prioritized
    fit_score + new_bin_penalty + lookahead_reward + dispersion_penalty
}

