    score += post_residual as f64 * 1.5;

    // 2. Harmonic Lookahead: If next_item can fit in current post_residual, prioritize it.
    // This creates "paired" items, reducing fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Fragmentation Avoidance: Penalize residuals that are too small to fit common items
    // (e.g., < 10) unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless existing options are poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // scaled by the fact that other bins might be available.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Fitting Pressure: If this is the only bin that can fit the item, 
    // prioritize it to avoid prematurely opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Distribution Smoothing: Use the mean_residual to balance the load across bins.
    // If the current bin is significantly "emptier" than the average, we prefer filling it.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
