    }

    // 5. New Bin Management: Discourage opening new bins unless necessary
    if bin_residual == bin_capacity {
        // High penalty for opening new bins; only choose if current options are abysmal
        score += 40.0;
        // Adjust based on progress: be more conservative with new bins as we reach the end of the stream
