pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin heavily early in the stream, 
    // but allow it if the current bin is inefficient later.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Reward bins that leave small residuals (Best Fit behavior).
    // Use a quadratic penalty for large residuals to favor tight packing.
    let residual_cost = post * post / 20.0;

    // Lookahead logic: if the next item is large, avoid leaving a residual 
    // that is just slightly too small to fit the next item.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // Favor bins that are already "tight" (low mean_residual) to maintain
    // consistency across the bin set.
    let consistency_bonus = (mean_residual - post) * 0.5;

    // If this is the only bin that can fit the item, give it a strong preference 
    // unless the fit is extremely poor (post_residual very high).
    let fit_urgency = if fitting_bins_count == 1 && !is_new_bin {
        -20.0 + (post * 0.2)
    } else {
        0.0
    };

    new_bin_penalty + residual_cost + lookahead_penalty + consistency_bonus + fit_urgency
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
