    // Penalty for creating a bin that is too small for common items, 
    // but reward filling bins tightly as the stream progresses.
    // If post_residual is very small (e.g., < 10), it's a "perfect fit" candidate.
    if post < 10.0 {
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead logic: If next_item_size is large, avoid leaving a small post_residual
    // that cannot accommodate the next item (Fragmented space penalty).
    if next_item_size > 0 {
        if post > 0.0 && post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Heuristic for opening a new bin:
    // Only open a new bin if the current bin is empty (bin_residual == bin_capacity)
    // and we have many open bins already, or if fitting_bins_count is low.
    if bin_residual == bin_capacity {
