    // Penalize new bin opening heavily initially, but relax as we approach end of stream
    let mut score = post_residual as f64;

    if is_new_bin {
        // High penalty for opening a new bin, reduced by how many items are left
        score += 45.0 * (1.0 - progress);

        // If the current item is very small, opening a new bin is usually wasteful
        if item_size < 30 {
            score += 20.0;
        }
    } else {
        // Reward bins that are "tight" fits, but avoid creating "dead space" (small residuals)
        // If post_residual is < 10, it's often a dead zone unless it's 0.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // Lookahead: If this bin can fit the next item, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }

        // If this is the only bin that fits the item (fitting_bins_count == 1), 
        // we should prioritize using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Balancing: If the average residual of open bins is high, prefer filling those bins
    // to keep the total number of active bins lower.
    if mean_residual > 40.0 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead zones" (small residuals) that are unlikely to accommodate 
    // future items, weighted by how far we are into the stream.
    // Small post_residual is dangerous if it's too small to fit typical items.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0 * (1.0 + progress);
    }

    // Heuristic: If we are near the end of the stream, favor filling bins tightly 
    // even if it consumes a bin that could have been used for a larger item.
    if next_item_size > 0 {
        let diff = (post as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5 * (1.0 - progress);
    }

    // Encourage using existing bins over opening new ones, but scale by 
    // the number of open bins to prevent excessive fragmentation.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalize opening a new bin unless existing bins have very poor fits.
        score += (open_bins_count as f64 * 15.0) + (mean_residual * 0.5);
    } else {
        // This is an existing bin. Reward filling it to reduce open_bins_count.
        score -= (bin_capacity as f64 - post) * 0.2;

        // If this is the only bin that fits, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Quadratic penalty for high mean residual to encourage bin consolidation.
    score += (mean_residual.powi(2) / bin_capacity as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

