        }
        // If the stream is nearly finished, prioritize packing existing bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 4. Harmonic Alignment: Penalize bins where the residual is a "dead zone" 
    // for common item sizes (e.g., leaving 20-30 space is often awkward).
    if post_residual > 20 && post_residual < 35 {
        score += 15.0;
    }

    // 5. Global Density: If many bins are open, push towards tighter packing
    // by increasing the cost of leaving any residual space.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

