        }
    }

    // Dynamic horizon: As we reach the end of the stream (progress -> 1.0), 
    // become more aggressive about filling gaps (Best Fit).
    score += (progress * 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Penalize small residuals that create "dead space" (e.g., 1-9) which are unlikely to fit future items.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 - (post / 10.0))
    } else {
        0.0
    };

    // Lookahead logic: If the next item is large, favor bins that keep more space open.
    // If next_item_size is 0 (end of stream), prioritize closing bins to reduce open_bins_count.
    let lookahead_factor = if next_item_size > 0 {
        (next_item_size as f64 / bin_capacity as f64) * (post_residual as f64 - next_item_size as f64).max(0.0)
    } else {
        (open_bins_count as f64) * 2.0
    };

    // Adaptive pressure: As the stream progresses, become more aggressive in packing tightly.
    // Use non-linear coupling: (post^2) to penalize large empty gaps heavily.
    let packing_pressure = (post * post) / bin_capacity as f64;

    // Reward bins that consolidate space (mean_residual coupling).
    // If this bin's post_residual is close to the mean_residual, we keep variance low.
    let variance_penalty = (post - mean_residual).abs() * 0.5;

    // New bin bias: If this is a new bin (bin_residual == bin_capacity), 
    // add a penalty that scales down as open_bins_count increases, 
    // but increases as we approach the end of the stream (to force consolidation).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (50.0 * (1.0 - progress)) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Final score assembly: Lower is better.
    let mut score = post + dead_space_penalty + packing_pressure + variance_penalty + lookahead_factor + new_bin_penalty;

    // If this is the last chance to fit the item in an existing bin, reduce penalty to prevent unnecessary new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
