    // 3. Lookahead Synergy: If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that are perfectly sized for the next item.
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize bins that will definitely force a new bin for the next item.
            score += 10.0;
        }
    }

    // 4. Fitting Scarcity: If this is the only bin that fits the current item, 
    // it is highly valuable; lower the score to prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression Weighting: As we approach the end of the stream, 
    // prioritize packing tightly to avoid creating new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // If this is a new bin, start with a high baseline to discourage opening bins unnecessarily.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Lookahead Synergy: If the post_residual can fit the next item, heavily reward it.
    // This creates a "perfect fit" chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
        // Further reward if the resulting residual is small (near-zero waste).
        if (post_residual - next_item_size) < 10 {
            score -= 20.0;
        }
    }

    // 3. Mean Residual Balancing: Avoid creating bins that are outliers compared to the average.
    // If the post_residual is significantly higher than the current mean, penalize it.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 4. Last-Chance Preservation: If this is the only bin that can fit the item, 
    // prioritize it even if the fit is poor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression Scaling: As the stream nears the end, become more aggressive 
    // about minimizing the number of bins (penalize opening new ones more).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the smallest residual.
    // The base score (post_residual) already incentivizes Best Fit.

    // 2. Penalty for creating "dead space":
    // If we leave a small gap that is unlikely to fit future items, it is wasted.
    // If post_residual is small (e.g., < 10), it is very hard to fill.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // 3. Lookahead integration:
    // If the next item is large and won't fit in this post_residual,
    // we should prioritize bins that leave enough space for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize this bin because it cannot accommodate the next item.
            score += 15.0;
        } else {
            // Reward this bin because it CAN accommodate the next item.
            score -= 10.0;
        }
    }

    // 4. Global state management:
    // If we are late in the stream, be more aggressive about filling bins (lowering score).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // 5. New Bin logic:
    // If the bin is brand new (residual == capacity), we only want to pick it if
    // the existing bins are "crowded" or offer very poor fits.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the current mean residual is already quite low
        // or if we have very few fitting bins.
        if mean_residual > 30.0 {
            score += 40.0;
        } else {
            score += 60.0;
        }
    }

    // 6. Last-chance logic:
    // If this is the only bin that can fit the item, we are forced to use it.
    // However, if we are opening a new bin, we don't want to penalize too hard.
    if fitting_bins_count == 0 && bin_residual != bin_capacity {
        score += 100.0; // Avoid closing a bin that is the only one fitting
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_r = post_residual as f64;

    // Penalize new bin creation exponentially as the stream progresses to consolidate bins
    let new_bin_penalty = if bin_residual == bin_capacity {
        (1.0 - progress).powf(0.5) * 40.0 + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Calculate how well the next item might fit into the remaining space
    // If next_item_size fits perfectly, we prioritize this bin (lowering the score)
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        let fit_tightness = (post_residual - next_item_size) as f64;
        -15.0 * (1.0 - (fit_tightness / 100.0))
    } else {
        0.0
    };

    // Penalize "slivers" (very small residuals) that are hard to fill later
    // The penalty is non-linear to discourage leaving space between 1 and 15
    let sliver_penalty = if post_residual > 0 && post_residual < 15 {
        (15.0 - post_residual as f64).powi(2) * 0.5
    } else {
        0.0
    };

    // Favor bins that are closer to the mean residual to keep distribution uniform
    let mean_alignment = (post_r - mean_residual).abs() * 0.1;

    // Final score: prioritize small post_residuals (Best Fit), modulated by lookahead and progress
    let score = post_r 
        + new_bin_penalty 
        + lookahead_bonus 
        + sliver_penalty 
        + mean_alignment;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a 'sliver' (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: if next item exists, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
