            score += 20.0;
        }
    }

    // Harmonic/Modulo logic: prioritize filling bins to specific thresholds
    // Favor bins that leave exactly 0 or 25 or 50 remaining space (multiples of 25)
    let remainder = post_residual % 25;
    if remainder == 0 && post_residual > 0 {
        score -= 30.0;
    }

    // Global pressure: if open_bins_count is high, penalize opening new bins
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // Discourage new bin if items are running out
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // If this is the only bin that fits the item, make it highly attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual, but impose a "dead-space" penalty for gaps that are 
