    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0;
        } else {
            score += 5.0; // Minimal cost to open if forced
        }
    }

    // Pressure factor: As we reach the end of the stream, prioritize tighter packing (lower residuals)
    // to reduce total bin count.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    // Penalize high open_bins_count to encourage consolidating items into fewer bins.
    score += (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily favor bins that can accommodate the next_item_size.
    // If the bin is brand new, we penalize it heavily unless the current open bins are extremely tight.

    let mut score = post_residual as f64;

    // 1. Penalize empty bins if we have space in existing bins
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0;
    }

    // 2. Lookahead optimization: reward bins that leave exactly enough space for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit reward: If post_residual is close to next_item_size, prioritize this bin
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 / (1.0 + diff)) * 2.5;
        } else {
            // Penalize if the next item won't fit, especially if this was the last viable bin
            if fitting_bins_count <= 1 {
                score += 20.0;
            }
        }
    }

    // 3. Fragmentation control: penalize bins that leave very small, unusable remainders (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Tightness bias: Favor bins that are already well-utilized (lower mean_residual)
    // This keeps the "used" bins dense and the "new" bins available.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // 5. Progression scaling: As we approach the end of the stream, prioritize closing gaps
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow more flexibility as we near completion
    let open_bin_penalty = if is_new_bin { 
        (1.0 - progress) * 45.0 + (open_bins_count as f64 * 0.5) 
    } else { 
        0.0 
    };

    // Calculate "Best Fit" behavior: prioritize bins where post_residual is small (tight fit)
    // but penalize extremely small residuals (e.g., < 5) if a larger item is expected next.
    let mut score = post_residual as f64;

    // Lookahead logic: if the next item is large and this bin can't fit it, 
    // we prefer smaller post_residuals now to avoid "wasting" space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0; // Penalty for stranding space that can't fit next item
        } else {
            score -= 5.0;  // Reward for leaving space that can potentially fit next item
        }
    }

    // Global state awareness: if we have many bins open, prioritize filling the ones with
    // the least residual space (Best Fit Decreasing style) to keep the mean_residual low.
    if !is_new_bin {
        score += (bin_residual as f64 - mean_residual).abs() * 0.2;
    }

    // Critical constraint: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 50.0;
    }

    score + open_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
