    let bin_pressure = (open_bins_count as f64) * (1.0 - progress);
    score += bin_pressure * 5.0;

    // 4. Dead space avoidance: Penalize post_residuals that are too small 
    // to fit the smallest expected items (e.g., < 10) unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // 5. New bin handling: If bin_residual == bin_capacity, we are evaluating 
    // the cost of opening a new bin. We make this expensive unless the 
    // current open bins are all very poorly suited for the current item.
    if bin_residual == bin_capacity {
        score += 40.0 + (mean_residual * 0.5);
    }

    // 6. Last chance logic: If this is the only bin that can fit the item, 
    // prioritize it significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
