    } else {
        // Nonlinear coupling: Reward bins that leave space for the next item (Lookahead).
        // If the post_residual is close to the next_item_size, we reward it.
        if next_item_size > 0 {
            let diff = (post as f64 - next_item_size as f64).abs();
