        // Entropy control: Penalize bins that create "dead" space that is too small 
        // to hold the smallest possible items (assuming 10 as lower bound).
        if post < 10.0 && post > 0.0 {
            score += 20.0 * (1.0 - progress);
        }

        // Global efficiency: If the bin residual is significantly higher than the mean,
        // we penalize it to force consolidation into tighter bins.
        if post > mean_residual {
