}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating a new bin:
    // Only apply if the bin is empty. We scale this penalty by the progress 
    // to encourage consolidation in the final stages of the stream.
    if bin_residual == bin_capacity {
        // As the stream progresses, the cost of opening a new bin increases 
        // to discourage fragmentation, but remains a fallback for poor fits.
        score += 15.0 + (progress * 25.0);
    }

    // Lookahead coupling: If a future item exists, penalize residuals that 
    // are too small to accommodate the next item (Dead Space creation).
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            // Heavily penalize 'micro-residuals' that trap space
            score += (next_item_size as f64 - post) * 1.5;
