    }

    // Coupling with mean_residual:
    // If this bin's post_residual is significantly better than the global average,
    // reward it to keep the bin packing tight.
    if post < mean_residual {
        score -= (mean_residual - post) * 0.5;
    }

    // Fitting constraint:
    // If this is the only bin that can fit the item, prioritize it strongly
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Non-linear interaction:
    // Penalize the creation of bins that are too 'empty' relative to the 
    // current open bin count, balanced by the progression of the stream.
    score += (open_bins_count as f64 * 0.1) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize small "slivers" of space that are unlikely to fit future items.
    // We penalize post_residual values that are non-zero but below the minimum expected item size (approx 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead Synergy: If next_item_size is known, reward bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Strong reward for keeping the bin viable for the immediate next item.
        } else {
