        }
    }

    // 3. Density Balancing: If we have many open bins, prioritize filling the tightest one (Best Fit).
    // If fitting_bins_count is high, we are in a flexible state; if low, we are constrained.
    if fitting_bins_count > 1 {
        score += (bin_residual - post_residual) as f64 * 0.1;
