    // 4. New Bin Threshold: Discourage opening new bins unless the current best fit is extremely poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin. 
        // We scale this by the number of currently open bins to favor consolidation.
        score = 45.0 + (open_bins_count as f64 * 2.0);

        // If current mean_residual is high, we have plenty of open space, so penalize opening a new bin more.
        score += mean_residual * 0.5;
