    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 25.0;
    }

    // 4. Fitting Bin Urgency: If this is the only bin that can fit the item, 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean residual normalization: Prefer bins that stay close to the average utilization.
    // This helps keep packing density uniform across active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit: Penalize large post_residuals to keep bins tight.
    // 2. New Bin Penalty: If this is an empty bin, add a heavy weight to discourage 
    //    opening new bins unless the fit in existing bins is extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // 3. Lookahead Matching: If the next item fits perfectly into the current post_residual,
    //    heavily reward this bin to create a "combo".
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= (50.0 / (diff + 1.0));
        } else {
            // Penalize if we are creating a residual that is too small to fit the next item.
            score += 15.0;
        }
    }

    // 4. Mean Residual Balancing: If this bin's post_residual is significantly better 
    //    than the current mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Critical Constraint: If this is the only bin that can fit the item, 
    //    reduce the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Progressive Strategy: As we approach the end of the stream, 
    //    prioritize closing bins (tighter fit) over new bin creation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: space left in bin after placement.
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that likely won't fit future items).
    // Specifically, residuals < 10 are often useless given item size range.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
