    }

    // 4. Global state adjustment: If many bins are open, prioritize smaller residuals 
    // to fill up existing bins and reduce the open_bins_count.
    if open_bins_count > 5 {
        score += post_residual as f64 * 0.5;
    }

    // 5. Dynamic Time Horizon: As we reach the end of the stream, prioritize 
    // packing efficiency over flexibility (avoid opening new bins).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 6. New Bin Penalty: Heavily penalize opening a new bin unless the fit is perfect 
    // or we are forced to (handled by the caller's logic vs this heuristic).
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we are forced to open a new bin, we want it to be a clean slate,
        // but we shouldn't prefer it over a tight fit.
    }

    // 7. Balance against mean_residual: If current bin is "better" than average, 
    // keep it as a candidate.
    if (bin_residual - item_size) < mean_residual as u32 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation exponentially as we approach the end of the stream
    let new_bin_penalty = if is_new_bin {
        (1.0 + progress * 5.0) * 25.0
    } else {
        0.0
    };

    // Calculate "Best Fit" behavior: prioritize bins that leave the least space (post_residual)
    // but penalize post_residual values that are too small to fit the next expected item.
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (very small residual that cannot fit common items)
    // We penalize post_residual if it's smaller than the next item but larger than 0.
    if post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Dynamic balancing: if we have many fitting bins, be more aggressive about filling
    // the tightest ones. If we have few, be more conservative.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).sqrt() * 2.0;
    }

    // Interaction term: penalize bins that deviate significantly from the mean_residual
    // to keep bin utilization uniform.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

