    // We favor tight fits (post_residual close to 0).
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward placements that leave room for specific harmonic fractions.
    // If post_residual is a multiple of common item sizes (e.g., 20, 25, 33), it is likely to be filled later.
    let harmonic_penalty = if post_residual > 0 {
        let rem = post_residual % 20;
        if rem == 0 { -15.0 } else { (rem as f64) * 0.5 }
    } else {
        -50.0 // Strong reward for perfect fills
    };
    score += harmonic_penalty;

    // 3. Lookahead logic: If next_item_size is large, avoid small post_residuals that would orphan the bin.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // This creates a "dead zone" for the next item.
