        } else if post_residual >= next_item_size {
            // This facilitates a perfect or near-perfect fit for the next item.
            score -= 20.0;
        }
    }

    // 4. Global State awareness:
    // If we have many open bins, we should be more aggressive about filling existing ones (penalty for new bin).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 5.0;
