    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits that leave little wasted space.
    // We penalize larger post_residuals heavily to favor packing items tightly.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: 
    // Reward bins that leave a post_residual that is a multiple of common item sizes (e.g., 20, 25, 33).
    // This creates "bins of opportunity" for future items.
    if post_residual > 0 {
        let remainder = post_residual % 20;
        score -= (20 - remainder) as f64 * 0.5;
    }

    // 3. Lookahead Sensitivity:
    // If the next item can fit in the current post_residual, reward this bin strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0;
    }

    // 4. New Bin Thresholding:
    // Only open a new bin if the current fitting options are extremely poor (i.e., they create large gaps).
    if bin_residual == bin_capacity {
        // If we have many open bins, opening a new one is expensive.
        // If we have very few, it's cheaper.
        score += (open_bins_count as f64 * 15.0);

        // If there's an existing bin that can fit the item, penalize opening a new one significantly.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 5. Progression Scaling:
    // As we reach the end of the stream, prioritize closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    // 6. Mean Residual Balancing:
    // Avoid creating bins that are significantly "emptier" than the average bin.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize gaps that are too small to fit common items (10-20 range)
    // but large enough to be "wasted" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // 2. Lookahead optimization: If the next item can fit in the current residual,
    // prioritize keeping that space open.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Open bins pressure: Penalize opening new bins when many are already active,
    // unless the fit is extremely efficient (Perfect fit).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 5.0;
        if post_residual == 0 {
            score -= 40.0; // Reward perfect new-bin fit
        }
    }

    // 4. Fitting constraints: If this is the last chance to fit an item into an existing bin,
    // incentivize taking the spot to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // 5. Global state normalization: Favor bins that align with the current mean
    // to keep residuals uniform and increase future fitting probability.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // 2. New Bin Penalty: Heavily penalize opening a new bin unless the current state is critical.
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If we have many open bins, opening a new one is highly discouraged.
        score += (open_bins_count as f64) * 2.5;
    }

    // 3. Lookahead Logic: If the next item fits perfectly into this post_residual, prioritize this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Favor bins that keep enough room for the next item.
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize if the next item will be forced into a new bin because of this placement.
            score += 15.0;
        }
    }

    // 4. Mean Residual Balancing: Avoid creating bins that are significantly below the mean 
    // capacity utilization, as they become "dead" bins.
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 20.0;
    }

    // 5. Urgency: As the stream nears the end, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (1.0 - progress) * 50.0;
    }

    // 6. Last-Chance Logic: If this is the only bin that fits, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
