        if bin_residual == bin_capacity {
            score += 40.0;
        }
    }

    // 4. Global State Awareness: If we have many open bins, penalize opening a new one.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 * (open_bins_count as f64).min(5.0);
    }

    // 5. Fitting Logic: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Mean Residual Balancing: Encourage keeping bin residuals close to the average.
    // This helps prevent "outlier" bins that are either too empty or too full.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

