    // We heavily penalize large post_residuals to keep bins packed tightly.
    let mut score = post * post * 0.01;

    // Penalty for opening a new bin: Only do it if the fit is truly terrible or we are near the end.
    if bin_residual == bin_capacity {
        // If we have other options, penalize opening a new bin heavily, 
        // but scale this penalty by progress to be more aggressive as the stream ends.
        score += (100.0 - (progress * 50.0)) * (fitting_bins_count as f64 + 1.0);
    }

    // Lookahead logic: If the next item exists, penalize residuals that are too small to fit it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            // This bin is now "dead" for the next item; add a penalty.
