            score += (1.0 - progress) * 25.0 * (1.0 + open_bins_count as f64 * 0.1);
        }
    }

    // Balance the mean residual: discourage creating bins that deviate significantly 
    // from the current average packing density to maintain uniformity.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
