pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit strategy).
    // We want to minimize this, but we apply non-linear penalties to avoid fragmentation.
    let mut score = post_res;

    // Penalty for creating "dead space": 
    // If the post_residual is small (e.g., < 10), it is likely unusable for future items (min size 1).
    // We penalize very small residuals exponentially to force packing into larger gaps.
    if post_residual > 0 && post_residual < 10 {
