    // Progression logic: As we reach the end of the stream (progress -> 1.0),
    // become more aggressive about filling bins tightly to avoid opening new ones.
    // We reward bins that are already well-utilized (lower mean_residual).
    score += (mean_residual * progress) * 0.5;

    // New bin logic:
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // We only want to open a new bin if the existing options are extremely poor (high post_residual).
    // We add a "cost" to opening a new bin that scales with the progress of the stream.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins early; lower penalty as we finish the stream.
        score += 35.0 * (1.0 - progress * 0.5);

        // If there are other bins that could fit this, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    score
