pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the basic Best-Fit objective (minimizing post_residual)
    let mut score = post_residual as f64;

    // Penalty for creating a "fragmented" bin: if post_residual is small but not zero,
    // it likely won't fit future items (10..80 range).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: if the next item can fit in the post_residual space, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // If this is a brand-new bin (bin_residual == bin_capacity):
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no other choice (fitting_bins_count == 0)
        // or if the current mean_residual is very low (meaning existing bins are nearly full).
        if fitting_bins_count > 0 {
            score += 120.0; // Heavy penalty for opening new bins if others fit
        }

        // Dynamic thresholding based on stream progress:
        // As the stream nears the end, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 40.0;
    } else {
        // For existing bins, favor those that move the bin closer to the mean_residual
        // to maintain uniform fullness across the set.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Heuristic: If this is the last fitting bin, prioritize it to avoid opening a new bin later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score. Lower is better.
    // 1. Base cost is the post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead space" (very small residuals that are hard to fill).
    // If post_residual is < 10, it's often wasted space unless it's 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead integration: If the next item fits into the current post_residual, 
    // prioritize this bin to preserve future capacity.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 4. Global state: If we have many open bins, penalize opening a new one.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 5.0;
        // If there are bins that can fit the current item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 5. Dynamic time horizon: As we approach the end of the stream, 
    // prioritize closing bins (minimizing post_residual) more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Balance the mean residual: If this bin's post_residual is significantly 
    // higher than the mean, it's a poor fit.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: favor smaller post_residuals (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for creating "slivers" (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 + progress);
    }

    // If this is the last fitting bin, penalize the new-bin option heavily
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 60.0 + (40.0 * progress);
        }
    } else {
        // Influence of lookahead: if next_item_size is large, favor larger post_residuals 
        // to accommodate the next item in the same bin.
        if next_item_size > 0 {
            let space_needed = next_item_size as f64;
            let current_post = post_residual as f64;
            if current_post < space_needed {
                // Penalize tight fits if they block the next item
                score += (space_needed - current_post) * 1.5;
            }
        }

        // Encourage packing bins towards the mean to keep residuals uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Dynamic scaling based on stream progression
    // As we approach the end of the stream, discourage opening new bins
    score *= 1.0 + (0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic penalty for creating "dead zones" (< 10 units)
    // If post_residual is small but > 0, it's often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Pressure management: If many bins are open, prioritize filling the tightest one.
    // We penalize bins that leave too much space if we have many bins already open.
    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.5;
    }

    // 4. Harmonic class bias:
    // Prefer bins that result in residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This helps pack items of similar sizes together.
    if post_residual % 25 == 0 {
        score -= 10.0;
    } else if post_residual % 20 == 0 {
        score -= 5.0;
    }

    // 5. New bin thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless the 
    // current mean_residual is very low (meaning existing bins are almost full).
    if bin_residual == bin_capacity {
        if mean_residual > 15.0 {
            // Only open new if existing bins are significantly underutilized
            score += 40.0;
        } else {
            // Otherwise, heavily penalize opening new bins
            score += 80.0;
        }
    }

    // 6. Final scaling based on stream progression
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize leaving small gaps that are unlikely to fit future items.
    // If post_residual is in the range [1, 9], it is highly "dead".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: Reward placements that leave a residual capable of fitting the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary, 
    // but penalize keeping too many bins open if they are inefficient.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin
        score += 45.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward bins that bring the current mean residual closer to a "healthy" 20-30 range
        let deviation = (post_residual as f64 - 25.0).abs();
        score += deviation * 0.5;
    }

    // 4. Scarcity Logic: If this is the only bin that fits the item, prioritize it 
    // to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

