    // We add a slight bias to discourage creating "dead space" that is too small for common items.
    if post_residual < 10 {
        score += 20.0;
    }

    // 2. Lookahead Matching: If the post_residual can fit the next item, reward this bin.
    // This implements a primitive Best-Fit-Decreasing-like lookahead.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 45.0;
        } else if post_residual > 0 {
            // Penalize if the current fit prevents the next item from fitting here, 
            // but the space is otherwise wasted.
            score += 15.0;
        }
    }

    // 3. New Bin Management: If this is a new bin candidate, calculate its desirability
    // relative to the current state of the packing.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins that are already poorly utilized,
        // or if we are forced to (fitting_bins_count is low).
        if open_bins_count > 0 && mean_residual > 30.0 {
            score += 50.0; 
        } else {
            score += 35.0;
        }
    }

    // 4. Fitting Pressure: If this is the last bin that can fit the item, prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Global Efficiency: As the stream progresses, prioritize closing bins 
    // (tighter packing) over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Decreasing logic: heavily penalize large post_residuals (wasted space)
    // 2. Lookahead mechanism: if next_item_size fits in the post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Penalty for creating "slivers" (very small residual) unless it's a perfect fit
    if post_residual > 0 && post_residual < 8 {
        score += 25.0;
    }

    // 4. If this is a new bin, penalize it based on how many bins are already open
    //    We want to avoid opening new bins unless the existing ones are truly terrible fits
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.0);
    } else {
        // 5. If this is an existing bin, reward it if it's the only option
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // 6. Dynamic pressure: as we reach the end of the stream, be more aggressive about packing tightly
        if progress > 0.8 {
            score += (post_residual as f64) * 0.5;
        }
    }

    // 7. Global state: avoid bins that deviate significantly from the mean_residual
    //    We prefer bins that keep the average occupancy consistent
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish large post_residuals (Best Fit strategy)
    // We use a quadratic penalty to discourage leaving large empty gaps
    let mut score = (post_residual as f64).powf(1.8);

    // Lookahead logic: if the next item is large, we want a bin that can accommodate it.
    // If post_residual is smaller than the next item, we penalize it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 150.0 * (1.0 - progress);
        }
    }

    // New bin penalty: discourage opening new bins unless the fit is extremely poor
    // or we are nearing the end of the stream where consolidation is harder.
    if is_new_bin {
        // Dynamic thresholding: as we progress, we become more conservative about opening new bins
        score += 85.0 + (progress * 40.0);

        // If there are other bins that could fit this, heavily penalize opening a new one
        if fitting_bins_count > 0 {
            score += 200.0;
        }
    } else {
        // Reward bins that have a residual close to the global mean, 
        // promoting uniform packing across all open bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Final scaling: favor bins that result in small residuals specifically 
    // when the current item is large, to save room for smaller ones later.
    if item_size > 60 {
        score -= (100 - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (the "fragmentation trap").
    // If post_residual is in (0, 10), it is likely to become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Density Balancing: If we are late in the stream, favor tighter packing (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    // 4. Fitting Constraint: If this is the only bin that can fit the item, prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the current residual is extremely poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 35.0;

        // If we have many open bins already, make it harder to open another one (avoid fragmenting)
        score += (open_bins_count as f64) * 2.0;

        // If the mean residual of current bins is high, we should try to use them instead of new ones.
        score += mean_residual * 0.2;
    }

    // 6. Modulo Harmonic Alignment: Reward residuals that are multiples of 25 (common packing alignment).
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

