    // (e.g., < 10) but too large to be zero.
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 - (post_residual as f64 * 3.0);
    }

    // 2. Open Bin Pressure: Penalize opening new bins heavily unless the fit is perfect.
    // If this is a new bin (bin_residual == bin_capacity), increase cost significantly.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many open bins, penalize opening another one even more.
        score += (open_bins_count as f64) * 2.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }

    // 4. Fitting Bin Scarcity: If this is the last bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Global Efficiency: If the current bin's residual is significantly better than the mean,
    // favor it to keep the average bin density high.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Progress Scaling: As we approach the end of the stream, prioritize closing bins
    // by being more lenient with small gaps.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small for common items, but too large to be efficient)
    // We penalize post_residual heavily if it's in the [1, 9] range, as these are rarely useful.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead matching: Reward bins where the post_residual can perfectly (or near-perfectly)
    // accommodate the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        if post_residual >= next_item_size {
            // Strong reward for a "tight fit" for the next item
            score -= (100.0 - diff) * 0.8;
        } else {
            // Penalize if the next item won't fit in the remaining space
            score += 20.0;
        }
    }

    // 3. Global density management: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Penalize opening a new bin proportional to how many bins are already open
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 4. Mean-residual alignment: Reward bins that stay close to the global mean, 
        // to keep bin utilization balanced.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Urgency: If this is the only bin that can fit the item, favor it slightly to avoid 
    // fragmenting space in other bins unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Progress factor: Be more aggressive in early stages, more conservative near the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Core objective: Minimize post_residual (Best Fit), but penalize "fragmentation" 
    // where post_residual is too small to accommodate likely future items.
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones": residuals smaller than the smallest likely item 
    // but larger than 0 are often inefficient.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, 
    // heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Dynamic Thresholding: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to minimize new bin creation.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 4. Global state balance: If we have many open bins, penalize opening a new one 
    // by significantly increasing the base score for empty bins (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // Only open a new bin if we are forced to (no other good options) 
        // or if our current open bins are all very tight.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 5. Mean residual pressure: If the average bin is already very full, 
    // prioritize keeping the current bin's residual closer to the global mean.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow flexibility as the stream ends.
    // The "new bin" candidate has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize smaller post_residuals (Best Fit)
    // We add a non-linear term to penalize post_residuals that are too small (fragmentation)
    // or too large (wasted space).
    let mut score = post + (post * post / bin_capacity as f64);

    // Coupling: If fitting_bins_count is 1, this is the last chance to place the item
    // in an existing bin. Penalize new bin creation unless necessary.
    if is_new_bin {
        // Higher cost for opening a new bin early in the stream.
        score += (bin_capacity as f64 * 1.5) * (1.0 - progress).powf(0.5);

        // If we have many open bins, penalize opening another one.
        score += open_bins_count as f64 * 2.0;
    } else {
        // If it's an existing bin, reward placements that keep the mean_residual stable.
        // Penalty for deviating from the average bin fill state.
        score += (post - mean_residual).abs() * 0.5;

        // Lookahead heuristic: if next_item_size is large, favor larger post_residuals
        // to accommodate it later.
        if next_item_size > 0 {
            let space_needed = next_item_size as f64;
            if post < space_needed {
                score += (space_needed - post) * 2.5;
            }
        }
    }

    // Exponentially penalize creating bins that are nearly empty if it's the end of the stream
    if is_new_bin && progress > 0.8 {
        score -= (bin_capacity as f64 * 0.5) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
