    // 5. New Bin Control: If this is an empty bin (new bin candidate), 
    // penalize it unless fitting_bins_count is very low (forcing a new bin).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily discourage opening a new bin if we have options
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other options, normalize score to encourage selection
            score = 5.0;
        }
    }

    // 6. Mean Residual Balancing: If this bin is significantly emptier than the average,
    // it's a good candidate for smaller items, but a bad candidate for current placement.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is small but > 0, it creates a "sliver" 
    // that is likely unusable (less than the minimum item size roughly 10-15).
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 - (post_residual as f64 * 2.0);
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins if there are existing bins that could fit it.
        score += (open_bins_count as f64 * 12.0) + (fitting_bins_count as f64 * 5.0);
    }

    // 3. Lookahead Integration: If next_item_size is large, favor bins that leave enough 
    // room for it. If post_residual is smaller than next_item_size, it's a suboptimal fit.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0;
        } else {
            // Reward bins that can accommodate the next item perfectly.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 4. Global Efficiency: If the current bin is already very empty compared to the mean,
    // we want to prioritize filling it to keep the mean_residual low.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We want to minimize the gap left behind.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the next item fits in the current post_residual, 
    // heavily reward this bin to keep the next item packed tightly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
        // Further reward if it fills the bin almost perfectly
        if post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // 3. New Bin Thresholding: If this is an empty bin (new bin candidate),
    // only choose it if the current best option is very poor.
    if bin_residual == bin_capacity {
        // High base penalty for opening a new bin.
        score += 45.0;

        // If we have many open bins that can fit the item, opening a new one is inefficient.
        score += (fitting_bins_count as f64) * 10.0;

        // If the mean residual is already quite high, opening a new bin is less desirable.
        score += mean_residual * 0.5;
    } else {
        // 4. Distribution Balancing: If the current bin is significantly emptier than 
        // the mean of open bins, we prefer to fill it to normalize the state.
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
    }

    // 5. Progression adjustment: As we approach the end of the stream, 
    // minimize the use of new bins aggressively.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead: If next_item_size is large, favor bins that can accommodate it.
    //    If post_residual < next_item_size, we penalize this bin to save space for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 45.0 * (1.0 - progress);
        } else {
            // Strong reward if this bin can hold both current and next item
            score -= 20.0 * (1.0 - progress);
        }
    }

    // 3. New Bin Penalty: Heavily penalize opening a new bin unless it's necessary.
    // If we are choosing between an existing bin and a new one (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // If other bins exist that can fit the item, discourage opening a new one
            score += 150.0 * (1.0 - 0.5 * progress);
        } else {
            // If no other bin fits, this is the only option
            score -= 50.0;
        }
    }

    // 4. Global State Awareness: If many bins are open, try to pack tighter into existing ones.
    if open_bins_count > 0 {
        let density_penalty = (mean_residual - post_residual as f64).abs() * 0.2;
        score += density_penalty;
    }

    // 5. Last chance bias: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

