    let mut score = post;

    // Penalty for creating a "sliver" (fragmentation)
    // If post_residual is small but > 0, it's often a bad fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If current post_residual is smaller than next_item_size, we penalize the bin.
    if next_item_size > 0 {
