    }

    // New bin bias: if we are early in the stream, be more conservative about opening 
    // new bins (penalize the empty bin case).
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress);
    }

    // Interaction with mean_residual: avoid outlier bins that deviate too far from the mean.
    let dev = (post as f64 - mean_residual).abs();
    score += 0.5 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize near-empty fragments.
    // If post_residual is small (e.g., < 10), it's likely a "good" fit (Best-Fit principle).
    // If post_residual is large, we penalize it to force consolidation.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward placements that leave residuals divisible by common factors
    // of the capacity 100 (e.g., 20, 25, 50).
    if post_residual > 0 {
        let remainder = post_residual % 20;
        score -= (20 - remainder) as f64 * 0.5;
    }

    // 3. Lookahead Integration: If next_item_size is large, favor bins that can accommodate it.
    // If current post_residual is less than next_item_size, we penalize this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // 4. Scarcity/Efficiency: If this is the last fitting bin, prioritize it to avoid 
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Threshold: Discourage opening a new bin unless the current fit is catastrophic.
    // If bin_residual == bin_capacity (meaning this is a new bin), add a heavy penalty 
    // base unless we are at the start of the process.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Adjust penalty based on progress; as we reach the end, opening a new bin is more expensive.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 6. Mean Residual Balancing: Penalize bins that deviate significantly from the mean_residual
    // to keep the fill-levels uniform across open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
