    }

    // Adjust based on the mean residual of current bins to encourage uniform fill
    // If this bin's post-residual is much lower than the mean, it's a good packing candidate.
    score += (post_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
