    // Encourage filling bins that are already "emptier" than the mean to balance usage
    let residual_deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * residual_deviation;

    // Final scaling to ensure Best Fit logic remains dominant
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
