    // Base score is the post_residual (Best Fit principle)
    // We penalize larger post_residuals to favor tight packing.
    let mut score = post;

    // Penalty for creating a new bin:
    // If this is a new bin (bin_residual == bin_capacity), add a cost.
    // The cost decreases as the stream progresses, allowing more new bins towards the end.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress).powf(0.5);
    }

    // Lookahead logic:
    // If the next item is large, we want to leave enough room.
    // If current post_residual is smaller than next_item_size, we penalize it 
    // because it forces a new bin later.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Favor bins that align with the current mean residual to keep bins balanced.
    // This reduces the variance of residuals across open bins.
    let diff = (post - mean_residual).abs();
    score += 0.5 * diff;

    // If this is the only bin that can fit the item, we lower the score 
    // to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Non-linear coupling: penalize very small residuals (fragmentation) 
    // that are too small for common items (e.g., < 10).
    if post > 0.0 && post < 10.0 {
        score += 12.0 * (1.0 - (post / 10.0));
    }

    score
}

