    let mut score = post_residual as f64;

    // Penalty for creating 'fragmented' space that is too small for common items.
    // If post_residual is small (e.g., < 10), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
