    // Global state: If we have many open bins, prioritize finishing them (lower residual).
    // If we have few bins, be more conservative about opening new ones.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate. 
        // Only pick it if we are forced to (fitting_bins_count == 0) 
        // or if our current bins are all quite full (mean_residual is low).
        if fitting_bins_count > 0 {
            score += 60.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0;
        }
    } else {
        // If this bin is already open, penalize it if it's becoming too empty
        // relative to the mean of other bins, to keep bins balanced.
        if (post_residual as f64) > mean_residual {
            score += 5.0;
