    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to how much space is wasted 
    // by not using existing bins, scaled by progress to discourage new bins late-stream.
    if is_new_bin {
        score += (bin_capacity as f64 * 0.75) * (1.0 + progress);
        // Penalize new bin if we have many open bins that could have taken the item
        score += (open_bins_count as f64).powf(1.5);
    } else {
        // Reward placements that leave a residual which is a multiple of the next item 
        // to encourage future packing efficiency (Lookahead heuristic)
        if next_item_size > 0 {
            let remainder = post_residual % next_item_size;
            score += remainder as f64 * 0.5;
