        }

        // Coupling: If we are near the end of the stream, prioritize filling 
        // existing bins (lower post_residual) more aggressively.
        score += (post_residual as f64 * progress * 0.5);
    }

    // Discourage leaving too many bins open simultaneously
    score += (open_bins_count as f64).powf(1.2) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
