    // Targets the minimization of "fragmentation entropy" by balancing Best-Fit with a 
    // lookahead-aware pressure mechanism.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Best-Fit Penalty: Minimize post_residual.
    // We heavily penalize large post_residuals as they signify wasted space.
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class Coupling: 
    // If post_residual is small, it creates "dead space" that cannot fit common item sizes.
    // We penalize residuals that fall into the "unusable" range (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 3. Lookahead Sensitivity (The "Next Item" Harmonic):
    // If next_item_size can fit into the post_residual, we reward the bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // 4. Pressure Management:
    // When fitting_bins_count is low, we are running out of options.
    // If this is a new bin (bin_residual == bin_capacity), increase cost based on open bins.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with mean_residual to prevent premature expansion.
        score += 60.0 + (mean_residual * 0.5) + (open_bins_count as f64 * 2.0);
    } else {
        // Reward existing bins that keep the mean_residual high (consolidating space).
        score -= (mean_residual - post_residual as f64).abs() * 0.1;
    }

    // 5. Temporal Smoothing:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    if progress > 0.95 && bin_residual == bin_capacity {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" small gaps (dead space between 1 and 9).
    // These gaps are statistically likely to remain empty for the duration of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. If this is a brand-new bin (bin_residual == bin_capacity), apply a heavy penalty
    // proportional to the number of existing bins to discourage fragmenting space too early.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 1.5);
    }

    // 3. Lookahead optimization: If the next item is large and won't fit in this 
    // post_residual, apply a penalty to leave space for it (Best-Fit variant).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Pressure: If we are nearing the end of the stream, prioritize closing 
    // bins by rewarding smaller post_residuals more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0) * (post_residual as f64 / bin_capacity as f64);

    // 5. If this is the only bin that fits the item (fitting_bins_count == 1), 
    // give it a slight preference boost to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the basic Best-Fit objective: minimize remaining space.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely: 
    // If this is a new bin (bin_residual == bin_capacity) and there are existing bins that fit, 
    // heavily penalize the new bin unless the current item is very large.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 45.0 + (item_size as f64 * 0.5);
    }

    // Aggressive Lookahead:
    // If next_item_size is known, favor bins where the post_residual is close to the next_item_size.
    // This creates a "Perfect Fit" chain.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward bins that can accommodate the next item perfectly.
        if post_residual >= next_item_size {
            score -= (20.0 - (diff * 0.2));
        } else {
            // Penalize bins that leave just enough space to be useless for the next item.
            score += 15.0;
        }
    }

    // Adaptive thresholding:
    // If the post_residual is very small (< 5), it's likely "dead space".
    // Penalize tiny slivers that are hard to fill later.
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    // Equilibrium constraint:
    // If the current bin's residual is significantly below the mean_residual of all bins, 
    // it suggests we are fragmenting this bin more than others. 
    // Penalize placing items in bins that become "denser" than the current average.
    if (post_residual as f64) < (mean_residual * 0.8) {
        score += 8.0;
    }

    // Progression weight:
    // As we approach the end of the stream, prioritize closing bins (lower post_residual)
    // over lookahead optimization.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize "sliver" residuals
    // that are too small to fit any likely future item (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 + progress);
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // prioritize this bin significantly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Global State Awareness: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Exponential penalty for opening new bins as the stream progresses
            score += 40.0 + (open_bins_count as f64 * 5.0) + (progress * 20.0);
        }
    }

    // 4. Fitting Constraints: If this is the only bin that can fit the item, 
    // prioritize it to avoid forcing a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Residual Balancing: Encourage filling bins that are already "closer" to the mean
    // to consolidate empty space usage.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating "dead space": if the post_residual is too small to fit 
    // the smallest possible item (assumed 10) or next_item, penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead influence: If the next item cannot fit in this bin, penalize the residual
    // to encourage keeping larger spaces for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - progress.powi(2));
    }

    // Dynamic pressure: As the stream progresses, favor packing tighter (lower residual).
    // If fitting_bins_count is 1, it's a "last chance" fit; reward this to avoid new bins.
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 + progress);
    }

    // New bin bias: If this is an empty bin (bin_residual == bin_capacity),
    // penalize opening a new bin heavily unless the progress is near the end
    // or the mean residual of current bins is very low (indicating high fragmentation).
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress.powi(3)) + (mean_residual * 0.5);
    }

    // Normalize against fragmentation: Penalize bins that deviate significantly from the mean residual.
    score += (post_res - mean_residual).abs() * 0.2;

    score
}

