    // However, we penalize very small residuals that create "orphaned" space (< 10).

    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation) that is likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: If the next item fits into the post_residual, prioritize this bin.
