    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (lower post_residual is better)
    // We add a penalty for opening new bins that scales with the remainder of the stream
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post * (1.0 + 0.5 * (post / bin_capacity as f64));

    // Penalty for opening a new bin:
    // As the stream progresses, the cost of opening a new bin increases to prevent fragmentation.
    if is_new_bin {
        score += (bin_capacity as f64) * (1.5 - (0.5 * progress));
    }

    // Lookahead logic:
    // If the next item is large, we want to preserve space in bins that can accommodate it.
    // If post_residual is smaller than the next_item_size, we penalize the placement 
    // to keep the bin available for the next, larger item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 0.8;
        }
    }

    // Heuristic coupling:
    // Penalize bins where the post_residual is a "dead zone" (too small for most items, e.g., < 10)
    // but only if we have other open bins available to reduce fragmentation.
    if post > 0.0 && post < 10.0 && open_bins_count > 1 {
        score += 20.0 * (1.0 - (post / 10.0));
    }

    // Reward bins that bring the mean_residual closer to the ideal packing density (e.g., ~15-20% empty)
    // This stabilizes the distribution of residuals across open bins.
    let target_residual = 15.0;
    score += 0.3 * (post - target_residual).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // We prioritize bins that result in a tight fit.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class logic: Penalize residuals that are not multiples of common item sizes
    // This reduces fragmentation by keeping remaining space usable for future items.
    let residual_mod = (post_residual % 20) as f64;
    score += residual_mod * 1.5;

    // 3. Lookahead synergy: If the next item can fit in the post_residual, highly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 4. Threshold penalty: If we have many open bins, penalize opening a new one heavily.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 150.0 + (open_bins_count as f64 * 5.0);
        }
    } else {
        // 5. Last chance mitigation: If only one bin fits, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 6. Distributional adaptation: Use mean_residual to avoid over-filling bins
    // that are already very tight compared to the average.
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 10.0;
    }

    // 7. Progression scaling: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "orphaned" gaps (1-9) 
