    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (gaps too small for most items).
    // If post_residual is < 10, it is extremely difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Heuristic: If we have a lookahead item, prioritize bins that can accommodate both
    // the current item and the next item (Best Fit with lookahead awareness).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Pressure factor: If we have many open bins, we should be more aggressive 
    // about filling the tighter ones to minimize total active bins.
    score += (open_bins_count as f64) * 0.5;

    // If this is a new bin (bin_residual == capacity), penalize it unless 
    // the current open bins are all very poorly suited for the current item.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin
        score += 35.0;

        // If there are bins that CAN fit the item, discourage opening a new one
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // Reward bins that have a residual close to the mean, promoting balanced filling
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual, but reward tight fits that approach 0.
    // If post_residual is 0, this is a perfect fill.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead optimization: If the next item fits into the post_residual, 
    // highly reward this bin to create a "double-fill" cluster.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further favor if the remaining space after next_item is small
        let remaining_after_next = post_residual - next_item_size;
        score -= (10.0 - remaining_after_next as f64).max(0.0);
    }

    // 3. Prevent fragmentation: Penalize bins that leave behind a gap too small 
    // for the smallest expected items (e.g., < 10), unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global balance: If this is an empty bin, only use it if existing 
    // bin options are poor (high residuals).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 35.0;
        // If there are many open bins, we should prefer reusing them
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Adaptive pressure: As the stream progresses, become more aggressive 
    // about filling existing bins to reduce total bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    // 6. Mean-residual alignment: Penalize bins that deviate significantly from 
    // the mean residual of open bins to keep bin states uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

