    }

    // 5. Fitting count: If this is the only bin that fits, prioritize it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Balance: Penalize bins that deviate significantly from the mean_residual 
    // to keep the packing density uniform across all active bins.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize residuals in the [1, 15] range significantly, as they are hard to fill.
    if post_residual > 0 && post_residual < 16 {
        score += (16.0 - post_res) * 5.0;
    }

    // Lookahead logic: If the next item is large, prioritize keeping space open.
    // If next_item_size > post_residual, we penalize this bin to save it for smaller items.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size as f64 - post_res) * 0.5;
    }

    // Dynamic pressure: As the stream nears the end, we become more aggressive 
    // about using existing bins rather than opening new ones.
    // We increase the penalty for empty bins as progress increases.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 + progress * 2.0);
    }

    // Coupling: If fitting_bins_count is low, we are running out of options for this item.
    // Reduce the score to prioritize fitting into existing bins to avoid opening a new one.
    if fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64).ln() * 2.0;
    }

    // Interaction term: Penalize bins that deviate from the mean residual of current bins.
    // This promotes "uniform" packing, keeping residuals similar across bins.
    let residual_variance = (post_res - mean_residual).abs();
    score += residual_variance * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

