        score = 45.0;

        // If we have many bins open, penalize opening another one.
        score += (open_bins_count as f64) * 2.0;

        // If we are near the end of the stream, penalize new bins more aggressively.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // Encourage using existing bins that have a residual similar to the mean residual
        // to keep bin utilization balanced.
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;

        // If this is the last fitting bin, prioritize it to avoid opening a new one later.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
