    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress).powi(2) * 50.0 + 20.0
    } else {
        0.0
    };

    // Calculate the 'closeness' to fit. Best fit (post_residual near 0) is ideal.
    // We penalize larger post_residuals quadratically to favor Best Fit.
    let fit_score = post.powi(2) / 100.0;

