    // If we have many bins open, penalize opening a new one (bin_residual == bin_capacity)
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting constraints
    // If this is the only bin that fits the item, make it very attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Tendency towards tighter packing relative to mean_residual
    // Prefer bins that stay closer to the current mean_residual to keep bin states uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the remaining space. Lower post_residual means a tighter fit.
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: reward smaller post_residual (tighter packing).
    // We penalize large post_residual exponentially to avoid fragmented space.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize this bin.
    if next_item_size > 0 && post_residual < next_item_size {
