    }

    // 3. Global State: Penalize opening new bins when many are already open.
    // If this is a new bin (bin_residual == bin_capacity), add a heavy penalty based on open_bins_count.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 0.8);
