    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Near end, prioritize fitting over perfect filling.
        score -= (1.0 - progress) * 20.0;
    }

    // 5. Fitting constraint: If this is the last bin that can fit the item, 
    // heavily reward it to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Balance: Penalize bins that deviate too far from the mean residual of current bins.
