    // If the bin is the last one that can fit the item, we lower its score
    // to prioritize keeping the number of open bins low.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 * (1.0 - progress);
    }

    // 4. Entropy mitigation:
    // If the residual is very small (e.g., < 5), it's a "tight" fit.
    // Reward this to favor filling bins completely.
    if post_residual < 5 {
        score -= 10.0;
    }

    // 5. Mean residual balance:
    // Penalize bins that deviate significantly from the mean residual of current bins
    // to maintain a uniform distribution of fill levels.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
