    // We prioritize bins where the post_residual is as small as possible.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: Reward placements that leave a residual 
    // that is a multiple of common item sizes (e.g., 20, 25, 33, 50).
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.8;

    // 3. Lookahead Synergy: If the next item fits into the post_residual, 
    // heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
