    // 5. New Bin Thresholding: If evaluating a fresh bin (bin_residual == bin_capacity),
    // only choose it if the current mean_residual is very high (indicating existing 
    // bins are already very full and inefficient).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            // Only open a new bin if the average space in open bins is smaller than the item itself
            score += (mean_residual * 2.0).min(100.0);
