        score -= (100.0 / (diff + 1.0));
    }

    // 3. Prevent fragmentation: If we have multiple bins, penalize opening a new one 
    // unless the current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        // This is a new bin. Penalize it based on how many bins are already open 
        // and how much space is wasted on average.
        score += (open_bins_count as f64 * 10.0) + (mean_residual * 0.5);
    } else {
        // This is an existing bin. Reward filling it up to leave "clean" space.
        // Harmonic alignment: prefer residuals that are large chunks of capacity.
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

