    // If we have many open bins, penalize the creation of new ones or bins with 
    // high post_residuals to force consolidation.
    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.8;
    }

    // 5. Fragmentation penalty:
    // If the post_residual is small but not zero (the "dead space" trap), penalize it 
    // unless the mean_residual of all bins is also small (indicating global tightness).
    if post_residual > 0 && post_residual < 10 {
        if mean_residual > 15.0 {
            score += 25.0;
        }
    }

    // 6. Tightness reward:
    // Reward bins that are perfectly filled (post_residual == 0).
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space; we want to minimize this (Best Fit principle).
    let mut score = post_res;

    // 1. Penalize creating "dead zones" (small residuals that are hard to fill).
    // If post_residual is small but > 0, it's often worse than 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // 2. Lookahead coupling: If the next item fits into the current post_residual, 
    // reward this bin heavily to encourage packing pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Global efficiency: As we progress through the stream, penalize opening new bins 
    // (where bin_residual == bin_capacity) to conserve space for later items.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item, 
    // prioritize it to avoid forcing a new bin allocation unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. Mean residual equilibrium: Penalize bins that deviate significantly from the mean 
    // to keep the bin distribution uniform.
    let dev = (post_res - mean_residual).abs();
    score += 0.2 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

