    // to become unusable "fragmentation." Penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If we know the next item, penalize placements that
    // make the next item impossible to fit in this specific bin, if this bin is 
