    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // If we have many bins open, opening a new one is very expensive.
        if open_bins_count > 5 {
            score += 20.0;
        }
    } else {
        // 4. Tightness reward: If we are not opening a new bin, reward 
        // placements that bring the residual closer to the mean residual of other bins,
        // promoting uniform bin usage.
        let diff = (post_residual as f64 - mean_residual).abs();
        score -= diff * 0.2;
    }

    // 5. Last chance mitigation: If fitting_bins_count is 1, this is the only bin 
    // that can take the item. Reduce the penalty for poor fits to ensure we don't
    // open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
