    // 2. Incorporate Lookahead: If next_item_size is large, avoid bins that leave little room.
    // If next_item_size > post_residual, this bin is "dead" for the next step.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0;
    }

    // 3. Dynamic Thresholding: As the stream progresses, become more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;

    // 4. Global State Awareness:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many bins are already open.
    // We want to avoid opening new bins unless necessary (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin when others are available
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other bin fits, this is the only option, reduce penalty
            score -= 10.0;
        }
    }

    // 5. Balance the mean residual: 
    // If our current bin's residual is significantly higher than the global mean, 
    // it implies we are leaving "too much" space compared to other bins.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 6. Time-decay: Near the end of the stream, prioritize closing bins (lower residual) over saving space.
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

