    // We want to minimize this to keep bins tight.
    let mut score = post_res;

    // Penalty for leaving small "dead space" (e.g., 1-9) that is hard to fill later.
    // This creates a non-linear "valley" where small residuals are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_res + 1.0);
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // prioritize this bin significantly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 * (1.0 - progress);
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive
    // about filling existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Penalize opening a new bin heavily, scaling with progress.
