        // This promotes uniform distribution of space across bins.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Final scaling: favor bins that are nearly full towards the end of the stream
    score -= (bin_capacity - post_res) as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
