    // Balance the number of open bins. If we have many open bins, prioritize filling them
    // to keep open_bins_count low.
    let bin_pressure = open_bins_count as f64 * 2.5;
    score += bin_pressure;

    // 4. NEW BIN DISCOURAGEMENT:
    // If this is a brand-new bin (bin_residual == bin_capacity), add a significant cost
    // to ensure we only open a new bin if the existing options are truly poor.
    if bin_residual == bin_capacity {
        score += 35.0;
