        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 5. MEAN RESIDUAL ALIGNMENT:
    // Prefer bins that stay close to the mean residual to maintain uniform bin utilization.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

