    // If post_residual is between 1 and 9, it is extremely likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 + progress);
    }

    // Lookahead logic: If a future item exists, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        } else {
            // Reward bins that can accommodate the next item
            score -= 15.0;
        }
    }

    // Global state: Discourage opening new bins too early
    if is_new_bin {
