            score = 0.0; // Must open if no bins exist
        } else {
            // Gradually make opening new bins more expensive as the stream progresses
            // to encourage filling existing bins toward the end of the batch
            score += 40.0 + (30.0 * progress);
        }
    } else {
        // Encourage using bins that are already closer to the mean residual
        // to keep bin utilization balanced
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;

        // If this is the only fitting bin, prioritize it heavily to avoid fragmentation
        if fitting_bins_count == 1 {
