pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We prioritize bins that result in a tight fit.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Matching: Reward bins that perfectly accommodate the next item
    // If post_residual is close to next_item_size, we favor this bin to reduce future fragmentation.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 1.5;

        // Heavy penalty if we leave a gap that is too small for any future item
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }
    }

    // 3. Global Efficiency: If this is an empty bin, penalize based on current open bin count
    // This forces the algorithm to use existing bins unless they are truly inefficient.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 0.5);
    } else {
        // 4. Mean Residual Balancing:
        // Penalize bins that are significantly "tighter" than the current average to maintain balance,
        // unless the post_residual is near zero (perfect fit).
        if post_residual > 0 {
            let deviation = (post_residual as f64 - mean_residual).abs();
            score += deviation * 0.2;
        }
    }

    // 5. Urgency: As we approach the end of the stream, prioritize tight fits more aggressively
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Last-Chance Logic: If this is the only bin that can fit the item, discount the score
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing
    // We favor bins that result in small remainders.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Integration: If the next item fits into the post_residual,
    // we heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Last Chance Logic: If this is the only bin that can fit the item,
    // minimize the penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 4. Global State Balancing: If we are late in the stream, favor using existing bins
    // over opening new ones to consolidate usage.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 + progress);
        if open_bins_count > 0 {
            score += mean_residual * 0.2;
        }
    }

    // 5. Dead Space Avoidance: Penalize residuals that are too small to fit any
    // likely future items (e.g., < 10), as these become permanent "wasted" slots.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 6. Dynamic Pressure: As the stream progresses, increase the cost of opening
    // a new bin relative to the average bin efficiency.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (open_bins_count as f64 / (1.0 + mean_residual)) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1..9) especially as the stream progresses.
    // Small residual gaps are "dead space" that rarely fit future items.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * (1.0 + progress * 5.0)
    } else {
        0.0
    };

    // Reward bins that maintain a high mean residual (keeping bins "loose" for future large items).
    // As we approach the end of the stream, prioritize tight packing (Best-Fit behavior).
    let tightness_factor = (post / bin_capacity as f64) * (1.0 - progress);

    // Lookahead logic: if next_item_size is large, avoid leaving a residual smaller than it.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), apply a baseline cost.
    // We only open a new bin if the cost is lower than the best existing bin's score.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_base_cost = if is_new_bin {
        // Dynamic threshold: only open new bin if existing bins are very crowded (low mean_residual)
        // or if we are at the very beginning of the stream.
        let crowdedness = 1.0 - (mean_residual / bin_capacity as f64);
        35.0 + (crowdedness * 20.0) - (progress * 10.0)
    } else {
        0.0
    };

    // If only one bin fits, we are forced to use it; lower the score to make it attractive.
    let forced_fit_bonus = if fitting_bins_count == 1 && !is_new_bin { -20.0 } else { 0.0 };

    post + dead_space_penalty + (tightness_factor * 10.0) + lookahead_penalty + new_bin_base_cost + forced_fit_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor smaller post_residual (Best Fit)
    // 2. Penalty for creating "dead space": If post_residual is in the range (0, 10), it's likely unusable.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // 3. Lookahead logic: If a bin can fit the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
        // Further reward if the post-post residual is very small (perfect fit).
        let post_post = post_residual - next_item_size;
        if post_post < 5 {
            score -= 20.0;
        }
    }

    // 4. Harmonic/Modular pressure: Favor bins that align with common item size increments (e.g., 20, 25, 33).
    // This helps group similar items together.
    let harmonic_alignment = (post_residual % 20) as f64;
    score += harmonic_alignment * 0.5;

    // 5. Global state adjustment: If we have many bins open, penalize opening a new one heavily.
    // The "new bin" case has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 6. Scarcity adjustment: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 7. Progress normalization: Towards the end of the stream, prioritize closing bins (tight fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to be useful
    // (typically < 10) for future items, but only if they aren't zero (perfect fits).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Coupling: If next_item_size is known, penalize placements that
    // would prevent the next item from fitting in this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin, apply a threshold penalty based on how many items remain.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Only open a new bin if we have no other choice (fitting_bins_count == 0)
        // or if the current mean residual is already quite low.
        if fitting_bins_count > 0 {
            score += 100.0 * (1.0 - progress);
        } else {
            score -= 10.0;
        }
    }

    // 4. Distribution Balancing: Penalize bins that deviate significantly from the mean,
    // encouraging a uniform distribution of residuals across open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Efficiency Bias: Reward bins that are nearing capacity to consolidate space.
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (too small to fit typical future items)
    // If post_residual is small but > 0, it often wastes space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // If next_item_size fits in the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
        // Further reward if it is a "tight" fit (minimizing future waste)
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Pressure to consolidate:
    // If this is the only bin that can fit the item, prioritize it to avoid new bin creation.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // 4. Mean residual balancing:
    // Avoid creating bins that are significantly below the current average residual.
    if (post_residual as f64) < mean_residual {
        score += 15.0;
    }

    // 5. New bin logic:
    // If bin_residual == bin_capacity, this is the "Open New Bin" candidate.
    // Only choose this if current fitting bins are very poor fits (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty to prevent opening new bins unless necessary
        score = 65.0; 

        // If we are late in the stream, be slightly more conservative about opening new bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: reward smaller post_residuals (tighter packing)
    // We heavily penalize creating tiny, unusable gaps (< 10) unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    }

    // 2. Lookahead mechanism: prioritize bins that can accommodate the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - progress);
        } else if fitting_bins_count > 0 {
            // If we can fit the next item elsewhere, penalize this bin slightly
            score += 10.0;
        }
    }

    // 3. Global state balancing: discourage opening new bins if open bins have high mean_residual
    // This pushes the algorithm to fill existing partially empty bins first.
    if bin_residual == bin_capacity {
        // If it's a new bin, penalize based on how much space we are wasting across all bins
        score += mean_residual * 0.5;
        // As the stream progresses, make it harder to open new bins
        score += 30.0 * progress;
    } else {
        // If it's an existing bin, reward it based on how much it helps reduce global waste
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // 4. Critical threshold: if this is the only bin that fits, force selection
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post-residual (Best Fit).
    // Penalize large empty spaces to keep bins tight.
    let mut score = post.powf(1.5);

    // Dynamic adaptation: As the stream progresses, prioritize closing bins
    // by penalizing the use of new bins more heavily.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress and the difficulty
        // of fitting current items (mean_residual).
        score += 150.0 * (1.0 + progress) * (1.0 + mean_residual / bin_capacity as f64);
    } else {
        // Interaction: If lookahead indicates the next item is large, 
        // favor bins that leave enough room for it.
        if next_item_size > 0 {
            let next_item = next_item_size as f64;
            if post < next_item {
                // Heavy penalty for stranding the next item if it's large.
                score += (next_item - post).powf(2.0) * 0.5;
            }
        }
    }

    // Encourage filling bins that have lower-than-average residual to maintain uniformity.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 5.0;
    }

    // If this is the last chance to fit the item in existing bins, 
    // provide a significant incentive to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals.
    // We want the post_residual to be as close to 0 as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy (Harmonic coupling):
    // If next_item fits in the remaining post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation Penalty:
    // If post_residual is small (e.g., < 10) but not 0, it creates "dead space" 
    // that rarely fits future items. Penalize these "sliver" residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Threshold Logic for New Bin vs Existing:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if
    // the current open bins are forced into bad fits (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if an existing bin can fit the item
            score += 45.0 + (open_bins_count as f64 * 2.0);
        } else {
            // We are forced to open a new bin
            score = 0.0;
        }
    }

    // 5. Mean residual balancing:
    // Try to keep the average residual of open bins consistent to avoid 
    // creating many bins with very low capacity.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // 6. Progression scaling:
    // As we approach the end of the stream, be more aggressive with packing
    // to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
