    // We penalize this heavily to force tighter packing into larger gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy:
    // If the next item fits into the post_residual, we reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
