}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base score is the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalty for creating unusable space:
    // If the post_residual is too small for any likely future items (e.g., < 10), 
    // it creates "dead space". We penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Matching:
    // If the next_item_size fits perfectly into the post_residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave exactly enough room for the next item
            score -= (20.0 * (next_item_size as f64 / (post_residual + 1) as f64));
        }
    }

    // 4. Global State Awareness:
    // If we have many open bins, penalize opening a new one (bin_residual == bin_capacity).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Efficiency Balancing:
    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // we should strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Mean Residual Balancing:
    // Try to keep bin residuals close to the global mean to avoid fragmented space.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that are hard to fill)
    // Residuals between 1 and 9 are notoriously difficult to fill in 10-80 distributions.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead mechanism: If next_item_size is large, favor larger residuals now.
    // If we have a large item coming, we want to leave space for it (or avoid opening a new bin later).
    if next_item_size > 60 {
        // If post_residual is small, we are "trapping" the next large item.
        if post_residual < next_item_size {
            score += 30.0;
        }
    }

    // 3. Global State: If we are late in the stream, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late game: prioritize filling existing bins even if fit is tight.
        score -= (1.0 - progress) * 20.0;
    }

    // 4. Strategic "New Bin" handling:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many 
    // existing bins could have taken the item.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current options are all "bad" (e.g., leaving a tiny residual).
        // If there are many fitting bins, opening a new one is almost always a mistake.
        score += (fitting_bins_count as f64) * 25.0;

        // Also penalize new bins if we have plenty of open bins already.
        score += (open_bins_count as f64) * 5.0;
    } else {
        // For existing bins, reward bins that are already "tight" to keep the number of active bins low.
        // We subtract a factor of the bin_residual to prioritize filling the fullest bins first (Best Fit).
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // 5. Dynamic Correction: If this is the last chance for an item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // We want to minimize the gap, but penalize tiny gaps that prevent future items.
    let mut score = post_res;

    // Penalty for "fragmentation": If we leave a tiny space that is unlikely to fit 
    // any future item, we penalize it. Since min item size is typically ~10, 
    // a post_residual < 10 is often "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item cannot fit in this bin, penalize this bin 
    // to encourage keeping it open for something that actually fits.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Dynamic thresholding based on stream progress: 
    // As we approach the end of the stream, prioritize closing bins (lower score 
    // for bins with low residuals) to avoid leaving too many half-empty bins.
    score += (1.0 - progress) * (mean_residual - post_res);

    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless the current fit is absolutely necessary.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, reduced slightly as stream progresses 
        // to accommodate packing density requirements.
        score += 45.0 - (20.0 * progress);
    }

    // Encourage filling bins that are already "near full" to reduce the total 
    // count of active bins.
    if fitting_bins_count > 0 {
        score -= (100.0 - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
