    }

    // Lookahead logic: Reward placements that create a residual capable of fitting the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            // Penalize if we block the next item from fitting in a bin where it otherwise could have
            score += 20.0;
        }
    }

    // Harmonic/Modulo logic: Favor residuals that align with common item size factors (multiples of 10 or 20)
    // This helps keep bins "clean" for future items
    let remainder = post_residual % 20;
    score += remainder as f64 * 0.5;

    // Efficiency bias: If this is the only bin that fits the item, make it very attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New bin management: Only open a new bin if the current fit is extremely poor
    // (High post_residual penalty for existing bins, but high base cost for new bins)
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high; only chosen if existing fits are even worse
        score = 45.0 + (open_bins_count as f64 * 0.1);
    } else {
        // Favor packing existing bins more tightly as the stream progresses
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

