    // As the stream progresses, we become more aggressive about filling bins tightly.
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 * (1.0 - progress).powf(0.5) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: favor small post_residual (tight packing).
