    // 3. Fragmentation Control: Penalize creation of new bins if existing bins can fit the item.
    // If this is a new bin (bin_residual == bin_capacity) and other bins could fit it, heavily penalize.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 100.0;
    }

    // 4. Density Balancing: Favor bins where the resulting residual aligns with the mean_residual
    // of the system, promoting uniform filling across all active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Harmonic Class Logic: Reward placements that leave a residual which is a multiple 
    // of 10 or 25, as these are "cleaner" remainders for future items.
    if post_residual % 10 == 0 {
        score -= 10.0;
    }
    if post_residual % 25 == 0 {
        score -= 15.0;
    }

    // 6. Progression Awareness: As the stream nears the end, prioritize tight packing 
    // over maintaining future flexibility.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

