    // Factor in lookahead: if the next item is large, we want to prioritize 
    // keeping large residuals available.
    let lookahead_penalty = if next_item_size > 0 {
        if post_residual < next_item_size {
            15.0 * (1.0 - progress)
        } else {
            -5.0 * (next_item_size as f64 / bin_capacity as f64)
        }
    } else {
        0.0
    };

    // Favor bins that align with the global average to keep bin states uniform
    let uniformity_bonus = (post_r - mean_residual).abs() * 0.5;

    // Final score: minimize post_residual (Best Fit) while applying non-linear penalties
    // for dead space, lookahead mismatch, and premature new bin opening.
    post_r + new_bin_penalty + dead_space_penalty + lookahead_penalty + uniformity_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Penalty: We penalize larger post_residuals to encourage tight packing.
    // However, we apply a non-linear weight to reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact fits for the lookahead item
            let fit_diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - fit_diff) * 0.5;
        } else {
            // Penalize creating a bin that cannot fit the next item if we are constrained
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This helps in aligning future items into slots.
    let harmonic_alignment = (post_residual % 20) as f64;
    score += harmonic_alignment * 0.2;

    // 3. Fragmentation Control: If this is the only fitting bin, prioritize it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. Global Density Awareness: If we are late in the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 2.0;
    }

    // 5. New Bin Threshold: If this is a new bin, apply a significant penalty.
    // We only open a new bin if the current fit is extremely poor (post_residual is large).
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If the item is large, opening a new bin is less penalized than if the item is small.
        score -= (item_size as f64) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

