            score += 20.0;
        } else {
            // Reward bins that perfectly fit the next item (Best Fit logic)
            if post_residual == next_item_size {
                score -= 15.0;
            }
        }
    }

    // 4. Global Efficiency: If the bin is becoming very sparse, discourage further usage
    // to keep the mean_residual of the system healthy.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
