pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit principle)
    // We add a non-linear term to penalize bins that leave small, unusable gaps.
    // A gap < 10 is rarely useful for remaining items (10..80 range).
    let gap_penalty = if post < 10.0 && post > 0.0 {
        100.0 / (post + 1.0)
    } else {
        0.0
    };

    // Lookahead influence: If the next item is large, favor larger residuals in current bins.
    // We use a non-linear scaling of post_residual based on the next_item_size.
    let lookahead_factor = (next_item_size as f64 / bin_capacity as f64) * post;

    // Progress sensitivity: As the stream nears completion, become strictly Best Fit (minimize post).
    // Early on, allow more flexibility (higher post_residual) to keep bins balanced.
    let progress_weight = 1.0 - progress;

    // New bin penalty: If this is an empty bin (post == bin_capacity), 
    // penalize based on how many bins are already open and how many can fit the current item.
    let new_bin_penalty = if bin_residual == bin_capacity {
        // Only open a new bin if we have no choice (fitting_bins_count == 0)
        // or if our current bins are too crowded (mean_residual is low).
        if fitting_bins_count == 0 {
            0.0
        } else {
            (100.0 * (1.0 - progress)) + (open_bins_count as f64 * 5.0)
        }
    } else {
        0.0
    };

    // Combine terms:
    // We want to minimize the score, so we subtract rewards and add penalties.
    let mut score = post + gap_penalty + (lookahead_factor * progress_weight) + new_bin_penalty;

    // Favor bins that align with the mean residual to keep packing uniform
    let uniformity_bonus = (post - mean_residual).abs() * 0.5;
    score += uniformity_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
