    // Base score: favour tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening new bins prematurely
    if is_new_bin {
        score += 25.0; // Base cost to open a new bin
        // Increase penalty if there are bins that could have fit the item
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Encourage balanced usage: penalize bins that deviate from the mean residual
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Lookahead logic: If the next item is large, prioritize keeping space
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize placements that block the next item from fitting
            score += 30.0 * (1.0 - progress);
        } else {
            // Reward placements that leave enough space for the next item
            score -= 15.0 * (1.0 - progress);
        }
    }

    // Adaptivity: As the stream nears the end, prioritize filling bins to capacity
    // to avoid leaving trailing items in multiple bins.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // Exponential penalty for "dead space" (small residuals that likely won't be filled)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space. Smaller residual is generally better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "slivers" (very small unusable space) that are hard to fill later.
    // We penalize post_residuals that are positive but smaller than the smallest possible item (10).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * 5.0;
    }

    // Lookahead logic: if we know the next item, prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that maintain capacity for the next item.
            score -= 20.0 * (1.0 - progress);
        } else {
            // Penalize bins that would "starve" the next item.
            score += 15.0;
        }
    }

    // Dynamic pressure: As the stream progresses, tighten the constraint on opening new bins.
    // If we are near the end of the stream, prioritize filling existing bins heavily.
    if bin_residual == bin_capacity {
        // This is a new bin. Penalize opening it based on how many bins are already open.
        // As progress increases, the penalty for opening a new bin grows non-linearly.
        score += (open_bins_count as f64).powf(1.5) * (1.0 + progress * 2.0);
    } else {
        // For existing bins, reward fitting items into bins that are already "half-empty"
        // to keep the distribution of residuals balanced.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= (fill_ratio * 10.0) * (1.0 - progress);
    }

    // If this is the only bin that fits, prioritize it strongly to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) logic: penalize large post_residuals (wasted space)
    // 2. Penalty for creating "orphan" space (too small to fit typical future items)
    if post_residual < 10 {
        score -= 20.0; // Reward tight packing (near-perfect fit)
    } else if post_residual < 20 {
        score += 5.0;  // Moderate penalty for leaving small slivers
    }

    // 3. Lookahead logic: If the next item can fit in the current post_residual, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0; 
    }

    // 4. Harmonic class awareness: Penalize leaving remainders that don't align with common item size distributions
    // Items are 10-80; remainders near 25, 33, or 50 are often inefficient.
    let residual_penalty = ((post_residual as f64 - 25.0).abs() < 5.0) as i32 as f64 * 10.0;
    score += residual_penalty;

    // 5. Global state management:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless fitting_bins_count is 0 (i.e., we are forced to open a new one)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0; // Strong disincentive to open new bin if existing ones work
        } else {
            score -= 100.0; // Mandatory if no other options
        }
    }

    // 6. Progression dampening: As we approach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

