    let mut score = post_residual as f64;

    // Penalty for "Dead Zones": gaps too small to fit common items (below 10-15) are high-risk.
    // We penalize post_residual values that are non-zero but very small.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If next_item_size is large and post_residual is small, we create a trap.
    if next_item_size > 0 {
