        score += (open_bins_count as f64 * 5.0) * (1.0 + progress);

        // If we have fitting bins, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Reward keeping open_bins_count low by penalizing bins that make mean_residual too high.
        score += (mean_residual * 0.5);
    }

    // Final refinement: penalize fragmentation when the bin is nearly full but not empty.
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // However, we apply a non-linear weight to punish "near-miss" wastage.
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead Synergy: If post_residual can perfectly or nearly accommodate the next item, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item with minimal slack
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.8;
        } else {
            // Penalize creating a bin that is too small for the next item if it could have fit elsewhere
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 3. New Bin Thresholding: If this is an empty bin, evaluate the cost of opening it.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very low (bins are full)
        // or if we are nearing the end of the stream and need to clear space.
        let progress = step_index as f64 / total_items as f64;
        score += 45.0 - (mean_residual * 0.4) + (progress * 15.0);
    }

    // 4. Scarcity/Constraint Handling: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Mean Deviation: Discourage creating bins that deviate significantly from current mean_residual.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
