        let deviation = (post - (mean_residual - item_size as f64)).abs();
        score -= deviation * 0.5;
    }

    // Penalty for creating 'dead zones' (space too small for any likely item).
    // If post_residual is < 10 (minimum item size), it is likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - progress);
    }

    // If this is the last fitting bin, slightly lower the score to avoid 
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
