    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 2. Lookahead Coupling: If the next item can fit in the current post_residual, 
    // reward this placement heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Harmonic Packing: Favor bins that leave room for items that are "difficult"
    // to place (e.g., larger items). If the current post_residual is a multiple of 
    // common item sizes, it's structurally advantageous.
    let harmonic_penalty = (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // 4. Density Balancing: If we are late in the stream, be more aggressive
    // about filling bins tightly to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (open_bins_count as f64 / (fitting_bins_count + 1) as f64);

    // 5. Empty Bin Threshold: If this is an empty bin (bin_residual == bin_capacity),
    // only pick it if it's the only option or if our current open bins are too full
    // to accommodate the current item efficiently.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one fits.
            score += 150.0 - (progress * 50.0);
        } else {
            // No choice, must open new bin.
            score = 0.0;
        }
    }

    // 6. Mean Residual alignment: Penalize bins that deviate too far from the mean 
    // usage of current bins to maintain uniform packing density.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize leaving small, unusable gaps.
    // If post_residual is small but > 0, it is often a "dead" gap.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // reward this bin to ensure we don't strand the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty relative to current usage.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Tight Fit Preference: Reward bins that minimize post_residual (Best Fit logic).
    // This naturally favors bins that leave less space, but we adjust for mean_residual
    // to keep the distribution of bin fullness balanced.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Last Chance Logic: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Progression Scaling: As the stream nears the end, become more aggressive 
    // about filling existing bins to close out the problem.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) logic: prioritize smallest post_residual (tightest fit)
    // This is the baseline score.

    // 2. Lookahead Penalty/Reward:
    // If the next item fits perfectly into the current post_residual, drastically reduce score.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
