    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless no other bin can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 65.0; // Strong bias against opening new bins prematurely
        } else {
            score -= 10.0; // Must open if nothing else fits
        }
    }

    // 4. Global Balance:
    // If the post_residual is significantly below the current mean_residual, 
    // it indicates a "tight" bin. Reward this to keep open bins consolidated.
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // 5. Progression weighting:
    // As we approach the end of the stream, prioritize closing bins (tight fit) 
    // over keeping bins open for future items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
