    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: If this bin fits the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
