    // Strategic constraint: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Dynamic threshold: As we approach the end of the stream, prioritize 
    // filling existing bins more aggressively (minimizing open_bins_count).
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * progress * 5.0;
    }

    // Penalty for opening a new bin when existing capacity is available.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Only open a new bin if the average residual is already quite low,
