pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tightest fit (Best Fit logic)
    let mut score = post;

    // Penalty for creating fragments that are too small to fit future items (dead space)
    // We use the post_residual relative to the bin_capacity to identify high-fragmentation placements.
    // If post_residual is small but > 0, it is often worse than 0 (perfect fit).
    if post > 0.0 && post < 15.0 {
        score += 25.0 * (1.0 - (post / 15.0));
    }

    // Lookahead coupling: If the next item is large, penalize bins that cannot accommodate it
    // or bins that would leave suboptimal space for the next item.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if (post as u32) < next_item_size {
            // Penalty for stranding the next item
            score += 40.0 * (1.0 - progress);
        } else {
            // Reward bins that leave space matching the next item size
            let diff = (post - next_f).abs();
            score -= 10.0 * (1.0 - (diff / 100.0));
        }
    }

    // Dynamic thresholding: As the stream progresses, become increasingly conservative 
    // about opening new bins by penalizing the "New Bin" candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with progress to force consolidation
        score += 60.0 * progress;

        // If there is only one bin that can fit the item, opening a new one is highly discouraged
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Normalize against the global state: penalize bins that deviate significantly from the mean
    // to encourage bin balancing.
    let deviation = (post - mean_residual).abs();
    score += 5.0 * (deviation / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Harmonic Class logic: penalize residuals that are small but not zero (fragmentation)
    // If post_residual is < 10, it is likely "dead space" unless it is 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead integration: 
    // If next_item_size fits in the post_residual, prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Fitting constraints:
    // If this is the ONLY bin that can fit the item, we must prioritize it unless it's a terrible fit.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 5. New Bin Logic:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the current open bins are all "cluttered" (high mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 30.0 {
            score += 10.0;
        } else {
            score += 60.0; // Strong penalty for opening new bins prematurely
        }
    }

    // 6. Harmonic normalization:
    // Favor bins that result in residuals that are multiples of common item sizes (25, 50).
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    // 7. Progression scaling:
    // As we approach the end of the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
