    }

    // 5. Mean residual equilibrium: Favor bins that keep the mean residual balanced.
    // If the current bin's post_residual is lower than the mean, it's a good packing candidate.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps < 10 are hard to fill)
    // If post_residual is small but > 0, it is often worse than a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
