        } else if post_residual > next_item_size {
            // Reward bins that keep enough space for the next item
            score -= (next_item_size as f64) * 0.2;
        } else {
            // Penalize bins that cannot fit the next item when they could have
            score += 15.0;
        }
    }

    // 3. Balance usage across bins using mean_residual
    // If a bin's post_residual is significantly better than the mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 4. Threshold for opening a new bin
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // fitting_bins_count is low, indicating we are forced to open a new one.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 35.0; // Heavy penalty for opening new bins unnecessarily
        }
        // If we are forced (fitting_bins_count == 0), the penalty is bypassed
    }

    // 5. Dynamic scaling based on progression
    // Towards the end of the stream, prioritize packing tighter to avoid new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items)
    // Residuals < 10 are often unusable given the item range 10-100.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
