    }

    // 3. Global state: If we are near the end of the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 4. Fitting bins count logic: If this is the only bin that fits the item, 
    // force selection to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Penalize opening a new bin (bin_residual == bin_capacity) unless residuals are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 40.0;

        // If current mean residual is already high, opening a new bin is less penalized.
        score -= mean_residual * 0.5;
    }

    // 6. Prefer bins that keep the bin_residual closer to the mean_residual to maintain balance.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post-residual (Best Fit).
    // Heavily penalize large residuals to force tight packing.
    let mut score = post * post * 0.01;

    // Lookahead logic: If the next item can fit in the remaining space, 
    // reward this bin to preserve it for the future.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamic pressure: As the stream progresses, increase the penalty for 
    // opening new bins by rewarding existing bins that are nearly full.
    // We adjust the weight based on the mean residual of current bins.
    let density_penalty = (mean_residual - post) * progress;
    score -= density_penalty;

    // Penalty for creating "dead zones": If post_residual is small but 
    // too large for most items (e.g., < 10), it is a wasted fragment.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // New bin threshold control: 
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current packing is inefficient 
        // (i.e., we have few open bins or the current bins are too full to fit the next item).
        score += 40.0 + (open_bins_count as f64 * 0.5);
        if fitting_bins_count > 0 {
            score += 50.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space to prioritize filling bins (Standard Best-Fit)
    // The post_residual is the base. Smaller is better.

    // 2. Harmonic Class Logic: Reward placements that leave a residual which is a multiple 
    // of common item sizes (e.g., 20, 25, 33, 50).
    let harmonic_penalty = if post_residual > 0 {
        let remainder = post_residual % 25;
        if remainder == 0 { -10.0 } else { (remainder as f64) * 0.5 }
    } else {
        -50.0 // Perfect fit is highly rewarded
    };
    score += harmonic_penalty;

    // 3. Lookahead Synergy: If the next item can fit into the current post_residual, 
    // heavily reward this bin to create a "combo".
    if next_item_size > 0 && post_residual >= next_item_size {
