    // 4. Scarcity/Congestion: If this is the last fitting bin, avoid opening a new bin 
    // unless the fit is truly terrible (post_residual > 40).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // 5. New Bin Threshold: Discourage opening a new bin unless the current fit is 
    // extremely inefficient or the new bin is the only option.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if current fits are very poor (post_residual > 60)
            score += 70.0;
        } else {
            // No other choice
            score = 0.0;
        }
    }

    // 6. Global Trend: As the stream nears the end, become more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
