    // 3. Balance usage across open bins
    // If post_residual is significantly higher than the mean, we are wasting space
    if (post_residual as f64) > mean_residual {
        score += 5.0 * ((post_residual as f64 - mean_residual) / (bin_capacity as f64));
    }

    // 4. Manage bin count: Penalize opening a new bin unless the fit is extremely poor
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if we have many open bins that would be left with tiny, unusable residuals
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Must open a new bin
            score -= 100.0;
        }
    }

    // 5. Prefer tightest fit (Best Fit logic)
    score += (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
