    // especially as the stream nears completion.
    let gap_penalty = if post_residual > 0 && post_residual < 10 {
        20.0 * (1.0 - 0.5 * progress)
    } else {
        0.0
    };

    // Reward bins that tightly fit the current item, 
    // but favor leaving space for the next item if it's large.
    let lookahead_alignment = if next_item_size > 0 {
        if post_residual >= next_item_size {
            -15.0 * (next_item_size as f64 / 100.0)
        } else {
