    // or we are in the early stages where packing density is flexible.
    let new_bin_bias = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 { -50.0 } else { 40.0 + (progress * 30.0) }
    } else {
        0.0
    };

    // Quadratic term to favor bins with lower residuals (Best Fit behavior)
    // weighted by the mean residual to encourage uniform distribution.
    let efficiency_score = (post_res * post_res) / 100.0 + (post_res * (mean_residual / 100.0));

    efficiency_score + gap_penalty + lookahead_alignment + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

