        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Reward placements that create residuals which are multiples of common item sizes (e.g., 20, 25, 50).
    // This creates "harmonic" alignment for future packing.
    if post_residual % 20 == 0 {
        score -= 15.0;
    } else if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // Lookahead logic: if next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
        } else {
            // Penalize placing the current item if it blocks the next item from fitting
            // in a bin where it otherwise would have.
            score += 20.0;
        }
    }

    // Discourage opening new bins unless necessary.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the current fit quality is exceptionally poor.
            score += 50.0;
        } else {
            score -= 10.0;
        }
    }

    // Balance the global number of bins: penalize creating too many open bins.
    score += (open_bins_count as f64) * 0.5;

    // Favor bins that are already closer to the mean residual to maintain packing density uniformity.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual ranges that are 
    // too small to fit any likely future items (10-80 range).
    // If post_residual is between 1 and 9, it is highly likely to become "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits in the current post_residual, 
    // heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 150.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when existing ones can fit the item.
    // If this is a new bin (bin_residual == bin_capacity), increase cost significantly
    // based on the number of already open bins to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += 80.0 + (open_bins_count as f64 * 5.0);
    } else {
        // If it's an existing bin, reward it if it's the only one that fits, 
        // to prevent creating a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // 4. Global Consolidation: If the bin residual is getting close to the mean 
    // residual of other bins, reward it to encourage uniform filling.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Progression Weighting: Towards the end of the stream, prioritize 
    // closing bins (lower post_residual) over keeping them open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

