    }

    // 4. New Bin Thresholding: If this is an empty bin (new bin candidate).
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or 
        // if the item is too large to fit well into existing ones.
        // We add a high base penalty to prevent opening new bins prematurely.
        score += 65.0;

        // If we are near the end of the stream, discourage new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // 5. Scarcity Constraint: If this is the only bin that can fit the item, 
        // we MUST take it to avoid forced new bin creation.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
