pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the new-bin option specifically to favor using existing space
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 35.0 + (progress * 20.0) } else { 0.0 };

    // Primary objective: Minimize post_residual, but penalize "near-dead" space (small residuals < 10)
    // which are rarely usable for future items.
    let mut score = post + if post < 10.0 && post > 0.0 { 15.0 - post } else { 0.0 };

    // Lookahead: If next_item can fit in this post_residual, reward the bin
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 25.0 * (1.0 - progress);
    }

    // Efficiency: Penalize opening too many bins as the stream progresses
    score += (open_bins_count as f64 * progress * 5.0);

    // Contextual adjustment: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid unnecessary new-bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest residual.
    // This is already captured by score = post_residual.

    // 2. Penalty for creating "dead space":
    // Residuals below 10 are often hard to fill (since min item size is 10).
    // Heavily penalize residuals that are small but non-zero.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead optimization (k=2):
    // If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Further reward if it creates a "perfect fit" for the next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 4. Harmonic/Modulo pressure:
    // Try to keep bin residuals clustered to allow packing of specific item classes.
    // Penalize residuals that deviate significantly from the current mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. New Bin Thresholding:
    // If this is an empty bin (bin_residual == bin_capacity), only pick it if
    // the penalty of "wasting" space in existing bins is higher than the cost of a new bin.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is relatively high.
        // We only open a new bin if we cannot find a good fit elsewhere.
        score = 65.0 - (fitting_bins_count as f64 * 5.0);
    }

    // 6. Progressive scaling:
    // As we near the end of the stream, prioritize tightly packing existing bins
    // to avoid leaving trailing items in new bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We heavily penalize residuals in the (0, 10) range as they are practically useless.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // Lookahead logic: if the next item is large, avoid bins that would be too small to fit it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Pressure to consolidate: Penalize opening new bins, but scale by progress.
    // Early in the stream, be more permissive; late in the stream, be strict.
    if is_new_bin {
        score += 15.0 + (open_bins_count as f64 * (1.0 + progress));
    } else {
        // If this bin is the last chance for the current item, reward placing it here
        // to avoid the overhead of opening a new bin later.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Reward bins that keep the mean residual close to the ideal density
        // as we approach the end of the stream.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    // We penalize it based on how many bins are currently open to prevent premature expansion.
    if bin_residual == bin_capacity {
        score += 150.0 + (open_bins_count as f64 * 5.0);
    }

    // 2. Lookahead matching:
    // If the post_residual is close to the next_item_size, we reward this placement
    // to create a "perfect" fit for the subsequent item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward small differences, penalize large ones relative to next_item_size
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Mean residual balancing:
    // Try to keep bin residuals close to the global mean to avoid creating "outlier" bins
    // that are too full or too empty compared to others.
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.2;

    // 4. Scarcity avoidance:
    // If this is the only bin that can fit the current item (fitting_bins_count == 1),
    // we must prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 5. Progression damping:
    // As we approach the end of the stream, prioritize tighter packing (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: prefer tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
        // Heavily penalize new bin if existing bins are highly available
        score += (open_bins_count as f64) * 5.0;
    }

    // Lookahead: If next item is large, avoid creating small residuals that are hard to fill
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Penalty for stranding the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Reward creating residuals that fit the next item perfectly
        if post_residual >= next_item_size && post_residual < (next_item_size + 10) {
            score -= 15.0;
        }
    }

    // Global state awareness: discourage fragmented bins
    // If mean_residual is low, we want to keep it low
    if (post_residual as f64) > mean_residual {
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Criticality check: if this is the only bin that can fit, take it unless it's terrible
    if fitting_bins_count == 1 && post_residual > 5 {
        score -= 10.0;
    }

    // Dynamic threshold: as we approach the end of the stream, prioritize packing density
    if progress > 0.8 {
        score += post_residual as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post-residuals (Best Fit logic)
    // We penalize the "New Bin" case (bin_residual == capacity) to ensure we fill existing bins first.
    let mut score = post;

    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to progress. 
        // Later in the stream, we are more desperate to open new bins to avoid fragmentation.
        score += 150.0 * (1.0 - progress).powf(0.5);
    } else {
        // Non-linear coupling: 
        // Penalize bins that would leave a "dead zone" (e.g., 1-9 capacity left).
        // If post_residual is small but > 0, it's hard to fill later.
        if post > 0.0 && post < 10.0 {
            score += 40.0 * (1.0 - post / 10.0);
        }

        // Lookahead optimization:
        // If the next item fits better in this current bin's remaining space, prioritize this bin.
        if next_item_size > 0 {
            if post >= next_item_size as f64 {
                // Reward bins that can accommodate the next item perfectly
                score -= 20.0 * (1.0 - (post - next_item_size as f64) / 100.0);
            }
        }

        // Global state awareness:
        // If there is only one bin that can fit this item, prioritize it to avoid fragmentation.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Favor bins that align with the global average residual to keep bins balanced.
        let deviation = (post - mean_residual).abs();
        score += 0.5 * deviation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #946: Harmonic-Residual Coupling
    // Objectives: 
    // 1. Minimize post_residual (Best Fit).
    // 2. Penalize "near-empty" bins (fragmentation).
    // 3. Anticipate the next item (Lookahead alignment).
    // 4. Thresholding based on capacity fractions.

    let mut score = post_residual as f64;

    // Penalty for creating a "bad" residual: 
    // Small residuals (1-5) are often unusable (dead space). 
    // Penalize them heavily to force tight packing.
    if post_residual > 0 && post_residual < 6 {
        score += 15.0;
    }

    // Reward bins that align with the next item.
    // If the next item fits perfectly or near-perfectly into the new residual, 
    // prioritize this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs();
        if diff < 10 {
            score -= 10.0;
        }
    }

    // Discourage opening new bins unless the current options are poor.
    // If we are considering a new bin (bin_residual == bin_capacity), 
    // add a bias that scales with open_bins_count and the mean residual.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low,
        // suggesting that existing bins are too full to accommodate future items.
        score += 25.0 + (open_bins_count as f64 * 0.5) - (mean_residual * 0.2);
    }

    // Encourage filling bins that are already "half-open" (low residual)
    // rather than keeping many bins partially filled.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // Harmonic dampening: favor bins that leave a residual which is a 
    // multiple of common small item sizes (e.g., 10, 20).
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small, unusable gaps.
    // If post_residual is < 10, it is likely unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: Reward bins that fit the next item perfectly or leave enough space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward placement that accommodates the lookahead item.
            score -= 25.0;
            // Bonus for tight packing with the next item.
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Penalize creating a bin that cannot fit the next item if other bins might.
            score += 15.0;
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // The new bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many existing bins
        // or if there are other bins that could fit the current item.
        score += (open_bins_count as f64 * 5.0) + (fitting_bins_count as f64 * 10.0);
    } else {
        // Encourage using existing bins that are already "half-full" to keep mean_residual balanced.
        if (bin_capacity - bin_residual) > (bin_capacity / 2) {
            score -= 10.0;
        }
    }

    // 4. Progressive Consolidation: As the stream nears the end, prioritize filling bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
