    // Heuristic: If we have a lookahead item, prioritize bins that can accommodate BOTH
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that are "perfect" for the pair
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize if this choice prevents the next item from fitting in this bin
            score += 15.0;
        }
    }

    // Dynamic threshold: As we near the end of the stream, prioritize filling existing bins
    // to avoid leaving partially filled bins behind.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // Encourage keeping the mean residual low across all bins
    if post_residual > mean_residual as u32 {
        score += 5.0;
    }

    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the item is very large or if we have too many fragmentation-prone bins
        if item_size < 60 && open_bins_count > 0 {
            score += 40.0;
        }
        // Penalize opening a new bin if we have plenty of fitting options
        score += (fitting_bins_count as f64) * 10.0;
    } else {
        // If it's a fitting bin, reward tighter fits (Best Fit decreasing)
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
