        score += (open_bins_count as f64) * 2.0;
    } else {
        // Encourage using existing bins that are closer to the mean residual.
        score += (post_residual as f64 - mean_residual).abs() * 0.1;
    }

    // 4. Scarcity/Urgency: If this is the only bin that can fit the item, 
