    score += progress * 20.0 * (open_bins_count as f64);

    // 4. Harmonic thresholding:
    // Favor bins that align with the mean residual to maintain uniform bin states.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. New Bin Penalty:
