        if post_residual < next_item_size {
            // Heavily penalize if this placement prevents the next item from fitting
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that leave space for the next item
            score -= (next_item_size as f64 * 0.5);
        }
    }

    // Dynamic pressure: As the stream nears the end, become more conservative
    // with opening new bins by penalizing the "New Bin" candidate (post_residual == bin_capacity)
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Interaction with mean_residual:
    // If this bin's post_residual is significantly better than the mean, favor it.
    // If it's worse, penalize it to maintain balance.
    score += (post - mean_residual) * 0.2;

    // Favor bins that are "last chance" (fitting_bins_count == 1) to avoid opening new bins,
    // unless the fit is extremely poor.
    if fitting_bins_count == 1 && post_residual > 5 {
        score -= 5.0;
    }

    // Non-linear penalty for creating "dead space" (very small residuals that are hard to fill)
    // 1-4 is usually unusable for items > 80, but here items are 1..100.
    // We treat residuals < 10 as "sliver" space, which is generally undesirable.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

