    }

    // 4. New Bin Thresholding:
    // If proposing a new bin (bin_residual == bin_capacity), apply a high cost
    // unless the open bins are all very poorly suited for the current item.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Global Efficiency Scaling:
    // As the stream nears the end, increase pressure to pack tighter (lower mean residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * mean_residual;

