    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Fragmentation Penalty: Avoid creating "dead space" (e.g., residual < 10).
    // If post_residual is small but > 0, it's often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global State: If fitting_bins_count is 1, we are at a "last chance" state.
    // If the current bin is the only one fitting, we are forced to use it unless 
    // the new bin score is better.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // 5. New Bin Logic: Penalize opening a new bin unless the remaining space 
    // in current bins is significantly worse than a fresh start.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very high (wasteful).
        if mean_residual > 40.0 {
            score -= 5.0;
        } else {
            score += 60.0; // Strong penalty for opening new bins unnecessarily
        }
    }

    // 6. Progression Scaling: As we near the end of the stream, prioritize 
    // compacting items to close out bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Be more aggressive in fitting current items to existing bins
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: punish large post-residuals to favor Best-Fit (Best-Fit Decreasing logic)
    let mut score = post_res.powf(1.5);

    // Lookahead logic: If the next item can fit into this post_residual, lower the score
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64).powf(1.2);
    }

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), increase the score 
    // based on how many other bins could have taken the item.
    if bin_residual == bin_capacity {
        // We only want to open a new bin if the existing fits are significantly worse
        // than the average residual.
        score += (fitting_bins_count as f64 * 50.0) + (mean_residual * 2.0);
    } else {
        // For existing bins, favor those where the post_residual is closer to 
        // the mean residual of all bins as the stream progresses.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * progress;
    }

    // Capacity utilization pressure: 
    // As we reach the end of the stream, prioritize tight fits (post_residual -> 0)
    // to minimize the number of bins left open.
    score += (1.0 - progress) * post_res * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual while penalizing "fragmentation" (small residues that cannot fit common items).
    // The "Harmonic" aspect: Favor residuals that align with common item size multiples (e.g., 20, 25, 50).

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if is_new_bin {
        score += 25.0; 
