        score += (open_bins_count as f64) * 2.0;
    } else {
        // Reward bins that are almost full (Best Fit principle)
        // If post_residual is 0, it's a perfect fit.
        score -= (100 - post_residual) as f64 * 0.1;

        // Lookahead heuristic: If the next item can fit in the remaining space, reward this bin.
        if next_item_size > 0 && post_residual >= next_item_size {
