        // Penalty for creating "dead space" (residuals < 10 are often unusable)
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    // Harmonic alignment: Penalize residuals that are not multiples of common item sizes (e.g., 20)
    // This encourages "clean" bins.
    let remainder = post_residual % 20;
    score += remainder as f64 * 0.5;

    // If this is the only bin that can fit the item, we must take it (lower the score).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Progression scaling: Be more aggressive about packing as we reach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
