    // We penalize post_residual exponentially if it's smaller than the next_item_size (wasted potential).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64).powf(1.5);
    }

    // Dynamic pressure: As the stream nears the end, be more conservative about opening new bins.
    // If fitting_bins_count is 1, it's the only option; avoid opening a new bin unless the fit is atrocious.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we progress through the stream.
        score += 15.0 + (progress * 50.0);
    } else {
        // Reward for using existing bins, scaled by how much capacity is left compared to the mean.
        // This encourages leveling out residuals across open bins.
        score -= (mean_residual - post) * 0.5;
    }

    // Heuristic coupling: If we are in the late game (high progress), prioritize clearing bins
    // that are close to full to minimize the number of open bins.
    if progress > 0.8 {
        score -= (bin_capacity as f64 - post) * 0.2;
    }

    score
}

