    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that is too small for any future item (if known).
    // If the post-residual is smaller than the smallest possible item (assumed 10), it is often wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
