    // Small residuals (< 10) are rarely useful for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item is large and this bin can't fit it, 
    // prioritize leaving room in OTHER bins by filling this one as tightly as possible.
    if next_item_size > post_residual && next_item_size > 0 {
