    let density_factor = (open_bins_count as f64 * 100.0) / (step_index as f64 + 1.0);
    score += (progress * 20.0) * (post_res / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // that scales down as the stream progresses, making it easier to open new bins late-game.
    if bin_residual == bin_capacity {
