    // This maintains "clean" space for future items.
    let harmonic_penalty = (post_residual % 20) as f64;
    score += harmonic_penalty * 0.8;

    // 4. New bin thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only choose it if the current
