    // Global state awareness: If we have many open bins, penalize opening a new one.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 {
            // Discourage opening a new bin if existing bins can still accommodate this item
            score += 60.0 + (open_bins_count as f64 * 2.0);
        }
        // Late-stage game: discourage new bins even more as capacity is wasted
        score += progress * 40.0;
    } else {
        // If this is the last fitting bin, reward picking it to avoid forced new bin later
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Balance the mean residual: discourage bins that deviate too far from the average
    // This promotes a more uniform distribution of space across bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left after placement.
    // Minimizing this usually leads to Best-Fit behavior.
    let mut score = post_res;

    // Penalty for creating "fragmented" space (small, unusable residuals).
    // If post_residual is small but > 0, it's often worse than 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if the next item fits into the current post_residual,
    // we prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
