    }

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is a new bin candidate.
    // We increase the penalty for new bins as the stream progresses.
    if bin_residual == bin_capacity {
        score += 45.0 + (30.0 * progress);
    }

    // Coupling with mean_residual: encourage bins that stay close to the average
    // to maintain a uniform packing density across open bins.
    let residual_diff = (post_res - mean_residual).abs();
    score += 0.5 * residual_diff * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

