    // We prioritize bins where the post_residual is either 0 (perfect fit) or large enough to host common items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Heavy penalty for creating unusable slivers
    } else if post_residual == 0 {
        score -= 10.0; // Reward perfect fits
    }

    // 2. Lookahead optimization: If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
