        }
    }

    // 3. Harmonic balancing: Penalize bins that deviate significantly from the mean_residual
    // This encourages "leveling" the load across open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 4. Thresholding: If this is the only bin that fits, we are forced to take it.
    // However, if we have multiple options, we favor bins that are already "half-full"
    // to keep the number of open bins low (Best-Fit approach).
    if fitting_bins_count > 1 {
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
