    // to maximize bin density (standard Best-Fit behavior).
    score += post_residual as f64 * 0.1;

    // 3. Lookahead Strategy: If the next item is large, avoid leaving a small residual.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 25.0;
    }

    // 4. Open Bins Pressure: Penalize opening a new bin if we have many active bins,
    // but encourage opening a new bin if the current fit is extremely poor (large residual).
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We only open a new bin if the average residual is already high (bins are under-utilized)
        // or if we have very few bins open.
        score += mean_residual * 0.5;
        if open_bins_count > 5 {
            score += 40.0; // Strong penalty for opening new bins if we have many
        }
    } else {
        // If this is the only bin that fits the item, make it very attractive.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Progression Weight: As we approach the end of the stream, prioritize packing
    // tightly to avoid trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
