    score += (post_residual as f64).powi(3) / 100.0;

    // 2. Lookahead optimization: If the next item exists, penalize bins that cannot fit it.
    // If post_residual is smaller than next_item_size, we effectively force a new bin later.
    if next_item_size > 0 {
