    // 3. Harmonic class alignment: Favor residuals that are multiples of common item sizes (20, 25, 33).
    // This reduces fragmentation by creating "standard" remaining space.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 2.0;

    // 4. New bin management: Only open a new bin if the current fit is catastrophic.
    // If this is an empty bin (bin_residual == bin_capacity), set a high threshold.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
