    if bin_residual == bin_capacity {
        score += 30.0 + (mean_residual * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Penalty for creating "orphan" small residuals (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead logic: if next_item_size fits in the new post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Further reward tight packing if next item is large
        if post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // 4. Harmonic thresholding: Favor filling bins to capacity (100)
    // If we are close to full, prioritize finishing the bin
    if post_residual < 5 {
        score -= 25.0;
    }

    // 5. New Bin Logic: Discourage opening new bins unless necessary
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if fitting_bins_count is low
        if open_bins_count > 0 {
            score += 60.0; 
        }
        // If it's the very first bin, keep it neutral
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // 6. Dynamic pressure: As the stream progresses, become more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 7. Penalize bins that create a gap that is unlikely to be filled by the mean_residual
    if (post_residual as f64) > mean_residual && post_residual > 15 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "orphaned" gaps (1-9) 
    // that are unlikely to fit future items. Balance against open_bins_count to prevent 
    // fragmentation of the bin pool.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": small residuals that are hard to fill.
    // If the post_residual is small (1-9), penalize it heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If the next item fits into the post_residual, 
    // reward this placement (Best Fit strategy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Fragmentation pressure: If we have many open bins, penalize opening a new one
    // or picking a bin that leaves a very small residual compared to the mean.
    if bin_residual == bin_capacity {
        // This is a candidate for a new bin. Penalize based on how many bins are already open.
        score += (open_bins_count as f64) * 2.5;
    } else {
        // If we are using an existing bin, reward it if it's close to the mean residual
        // to keep bin fullness balanced.
        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.1;
    }

    // 4. Scarcity pressure: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // tighten the requirements for opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small for future items but too large to be efficient)
    // If post_residual is small but > 0, it's often a bad fit unless it perfectly matches an item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead logic: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Bonus for "perfect fit" for the next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. Global state: If we have many open bins, prioritize filling existing ones to keep count low.
    // If this is the last chance for the current item (fitting_bins_count == 1), we are forced to pick it.
    // If fitting_bins_count == 0, this is the "new bin" call.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin
        score += 50.0;
        // Scale the penalty by current progression to avoid opening new bins late in the stream
        score += (step_index as f64 / total_items as f64) * 20.0;
    } else {
        // Prioritize bins that bring the residual closer to the global mean, reducing variance
        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.5;
    }

    // 4. Strategic constraint: If we are near the end of the stream, be more aggressive at packing
    // to minimize the final bin count.
    if step_index > (total_items * 9 / 10) {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score. Lower is better.
    // 1. Base penalty: The tighter the fit, the better (Best Fit).
    let mut score = post_residual as f64;

    // 2. Lookahead logic: If the next item can fit perfectly into the current post_residual, 
    // heavily reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Global state: Penalize opening new bins early in the stream.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have plenty of open bins or if we are early in the stream.
        score += 40.0 + (open_bins_count as f64 * 2.0) - (progress * 10.0);
    } else {
        // 4. Efficiency: Prefer bins that keep the global mean residual low.
        // If this bin's post_residual is below the mean, reward it.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }

        // 5. Last chance protection: If this is the only bin that fits the item, 
        // prioritize it strongly to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 6. Fragmentation control: penalize leaving very small gaps (e.g., 1-5) 
    // that are statistically unlikely to fit future items.
    if post_residual > 0 && post_residual < 6 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

