    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but not zero,
    // it is often unusable for future items (e.g., 1-9 range).
    if post_res > 0.0 && post_res < 10.0 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if the next item fits into the current post_residual,
    // we heavily reward this bin to preserve future capacity.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 40.0;
    }

    // Dynamic Pressure: As the stream progresses, we become more conservative about 
    // opening new bins. If fitting_bins_count is 1, we are at a "bottleneck" where
    // we must decide to use the last fitting bin or start a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize opening a new bin (where bin_residual == bin_capacity)
    // based on how many bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 0.5);
    }

    // Non-linear coupling: Favor bins where the resulting residual aligns with 
    // the mean residual of the system to maintain uniform packing density.
    let residual_diff = (post_res - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

