    // Harmonic class logic: favor bins that leave residuals divisible by common item sizes
    // or residuals that align with the mean_residual to keep space distribution uniform
    let residual_alignment = (post_residual as f64 - mean_residual).abs();
    score += residual_alignment * 0.5;

    // Threshold logic: If this is the last fitting bin, prioritize it to avoid opening a new one,
    // unless the fit is extremely poor (post_residual is very large).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
