    // Discourage opening new bins (bin_residual == bin_capacity) unless the fit quality
    // in existing bins is significantly worse than the capacity penalty.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // Adjust score based on progression to be more aggressive with packing as the stream nears the end
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
