    }

    // Lookahead: If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item perfectly
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize bins that would be too small for the next item
            score += 10.0;
        }
    }

    // Global State: If we have many open bins, prioritize tightening existing ones.
    // If we are near the end of the stream, be more aggressive about filling bins.
    let density_penalty = (open_bins_count as f64 - mean_residual / 10.0) * progress;
    score += density_penalty;

    // New Bin Handling:
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    // We only want to open a new bin if the current fit quality is very poor (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Must open a new bin, return a very low score
            score = -100.0;
        } else {
            // Penalize opening a new bin if other options exist, unless the fit is terrible.
            // Adjust threshold based on progress.
            score = 40.0 + (mean_residual * 0.5);
        }
    } else {
        // Prefer tight fits in existing bins
        score -= (100.0 - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

