    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // We scale the penalty based on how many bins are currently open and the progress in the stream.
    // Early in the stream, we are more conservative (high penalty).
    // Late in the stream, we are more aggressive to avoid leaving bins partially empty.
    if is_new_bin {
        let new_bin_penalty = 15.0 + (open_bins_count as f64 * 0.5) + (progress * 25.0);
        score += new_bin_penalty;
