        }
    }

    // Interaction term:
    // Penalize bins that deviate significantly from the mean residual.
    // This promotes tighter packing across all bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.25;

    // Final adjustment:
    // If this is the only bin that can fit the item, prioritize it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want to minimize post_residual, so it acts as the base.

    // 2. Harmonic Class Logic:
    // If the post_residual is small, it might be too small for future items.
    // If post_residual is in a "dead zone" (e.g., < 10), it is likely useless.
    if post_residual > 0 && post_residual < 10 {
