    // The smaller the post_residual, the better (Best-Fit principle).
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Coupling: If next_item_size is large, favor bins that can still accommodate it.
    // If next_item_size > post_residual, we penalize this bin because it won't fit the next item.
    if next_item_size > 0 && next_item_size > post_residual {
