    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Penalize if the current placement prevents the next item from fitting here,
            // especially if this is the only bin that could have fit it.
            score += 5.0;
        }
    }

    // 3. Adaptive thresholding: if we are late in the stream, be more aggressive about filling bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 4. Balance the load: penalize bins that deviate significantly from the mean residual.
    // We want to keep residuals tightly packed.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. New bin logic: discourage opening new bins unless the fit is excellent (Best Fit).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can accommodate the item.
            score += 45.0;
        } else {
            // If no other bin fits, this is a necessary evil.
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
