    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Dynamic horizon: as total_items approaches, become more aggressive with packing
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Progress factor: 0.0 at start, 1.0 at end
    let progress = step_index as f64 / total_items as f64;

    // Core objective: Minimize post_residual, but heavily penalize dead space that
    // falls below the threshold of the next expected item.
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is almost empty but not quite full enough
    // to accommodate common item sizes (Non-linear penalty for small residuals)
    if post_residual > 0 {
        score += (bin_capacity as f64 - post_residual as f64).powf(1.5) * 0.05;
    }

