    // we should prioritize bins that have a post_residual closest to the next_item_size
    // to minimize fragmentation.
    if next_item_size > 0 {
        let gap_diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += gap_diff * (1.0 - progress);
    }

    // Dynamic thresholding: As the stream progresses, prioritize closing bins
    // by penalizing the creation of new bins (if this is an empty bin)
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Higher penalty for opening a new bin as we reach the end of the stream
        score += (100.0 * progress) + (open_bins_count as f64 * 2.0);
    }

    // Reward bins that bring the mean residual closer to a "tight" packing state
    // (targeting ~10-15% residual space)
    let target_residual = 12.0;
    score += (post_residual as f64 - target_residual).abs() * 0.5;

    // Favor bins that are already "near-full" to consolidate space
    if fitting_bins_count > 0 {
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
