pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit approach).
    // We want to minimize post_residual, so lower values are naturally preferred.
    let mut score = post;

    // Penalty for creating "dead space": 
    // If post_residual is small (e.g., < 10), it is likely unusable for future items.
    // We heavily penalize very small residuals that are not zero.
    if post > 0.0 && post < 10.0 {
