    // Dynamic thresholding:
    // As the stream progresses, we become more conservative about opening new bins.
    // If bin_residual == bin_capacity, this is a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low (bins are full),
        // or if we have very few options.
        let openness_penalty = (open_bins_count as f64 * 2.0) + (mean_residual * 0.5);
        score += openness_penalty * (1.0 + progress);
    } else {
        // If the bin is already open, reward it based on how well it fits the current item
        // relative to the mean residual of all open bins.
        if post < mean_residual {
            score -= (mean_residual - post) * 0.5;
        }
    }

    // Special case for fitting_bins_count:
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1291: Harmonic Best-Fit with Lookahead Pressure.
    // Logic: Penalize small residuals (splinters) while favoring configurations that 
    // align with next_item_size to maximize bin density.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Splinter Penalty: If the post_residual is too small to fit common items (e.g., < 10),
    // it creates "dead space". We penalize these sharply.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0 / (post_residual as f64 + 1.0);
