pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but prioritize tight fits for the current item
    // and reserve space for the lookahead item (next_item_size).

    let mut score = post_residual as f64;

    // 1. Reward perfect fits or near-perfect fits (Best-Fit principle)
    // Penalize large post_residuals exponentially to avoid fragmented space.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin heavily to prevent opening a new bin later.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 5.0;
