    // 3. New Bin Penalty: Make opening a new bin expensive unless the current 
    // fits are extremely inefficient (e.g., they leave very little room for future items).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current open bins are all very tight 
        // and cannot accommodate the current item well.
        score += 45.0; 
        if fitting_bins_count > 0 {
            score += 30.0; // Heavy penalty for ignoring existing bins
        }
    }

    // 4. Mean Residual Balancing: If the current bin's post_residual is significantly 
    // worse than the mean, penalize it to encourage leveling out bin usage.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 2.0;
    }

    // 5. Progression awareness: As we approach the end of the stream, 
    // prioritize closing existing bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
