    }

    // 5. Dynamic Horizon: As we near the end of the stream, prioritize closing bins 
    // (tight packing) over keeping space open for future items.
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.5;
    }

    // 6. New Bin Penalty: If this is a new bin (residual == capacity), 
    // only open it if existing bins are truly poor fits.
    if bin_residual == bin_capacity {
