    // If next_item_size fits in the post_residual, reduce the score to prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64).powf(1.5);
    }

    // 3. Global Packing Efficiency:
    // If the bin is new (res == capacity), penalize it based on progress.
    // Early in the stream, we are more tolerant of new bins. Late in the stream, we are strict.
    if res == bin_capacity as f64 {
        score += (1.0 - progress) * 50.0 + (open_bins_count as f64 * 2.0);
    } else {
        // 4. Density Balancing:
        // Penalize bins that deviate significantly from the mean_residual of all open bins.
        // This encourages "leveling" the bins.
        score += (post - mean_residual).abs() * 0.5;
    }

    // 5. Scarcity Constraint:
    // If this is the only bin that fits the current item, prioritize it heavily.
    if fitting_bins_count == 1 && res != bin_capacity as f64 {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

