    }

    // Lookahead logic: if next_item_size is large, prefer bins with larger post_residuals
    // to accommodate it, unless we are near the end of the stream (progress -> 1.0).
    if next_item_size > 0 {
        let lookahead_diff = (next_item_size as f64 - post) * (1.0 - progress);
        if lookahead_diff > 0.0 {
