        score += (open_bins_count as f64 * 15.0) * (1.0 - progress * 0.5);
    } else {
        // Reward bins that are being filled towards capacity, especially late in the stream
        score -= (bin_capacity as f64 - post) * 0.1 * progress;
    }

    // Fitting count pressure: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
