pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We heavily penalize large post_residuals to prioritize filling bins near capacity.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Global State Balancing: 
    // If we have many open bins, penalize opening a new one significantly.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // Discourage opening a new bin if other bins can fit this item.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 4. Dynamic Horizon: As the stream progresses, become more aggressive in packing
    // by penalizing "loose" bins (those with high residual relative to the mean).
    let progress = step_index as f64 / total_items as f64;
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (1.0 + progress * 2.0);
    }

    // 5. Last Chance Heuristic:
    // If this is the only bin that can fit the current item, prioritize it to avoid 
    // fragmenting space across unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress and open bins
    // This discourages opening new bins late in the stream
    if is_new_bin {
        score += 15.0 + (progress * 50.0) + (open_bins_count as f64 * 2.0);
    } else {
        // Reward tight fits that leave space for lookahead
        // If next_item_size fits in the post_residual, apply a non-linear discount
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }

        // Penalize fragmentation: if post_residual is small but > 0, 
        // it creates 'dead space' that is hard to fill.
        if post_residual > 0 && post_residual < 15 {
            score += (15 - post_residual) as f64 * 2.5;
        }
    }

    // Adjust based on the mean residual of the system to maintain balance
    // If the mean residual is high, we prefer tighter fits (lower score)
    score += (mean_residual - post_residual as f64) * 0.1;

    // If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want to minimize post_residual, so it stays as the base.

    // 2. Harmonic Class Logic:
    // Penalize gaps that are unusable (e.g., < 10) unless they are exactly 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual == 0 {
        score -= 20.0; // Strong reward for perfect fills
    }

    // 3. Lookahead Logic:
    // If next_item_size fits in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Further encourage packing specific sizes that leave small remainders
        if post_residual - next_item_size < 5 {
            score -= 15.0;
        }
    }

    // 4. Thresholding based on fitting_bins_count:
    // If this is the only bin that fits the item, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. New Bin Penalty:
    // Only open a new bin if the score is significantly better than existing options.
    if bin_residual == bin_capacity {
        // High base penalty for opening a new bin, unless the stream is early
        let progress = step_index as f64 / total_items as f64;
        score += 60.0 * (1.0 - progress);

        // If we have many bins open already, resist opening more
        score += open_bins_count as f64 * 2.0;
    }

    // 6. Mean Residual Balancing:
    // Avoid bins that deviate significantly from the mean efficiency
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small gaps that are unlikely to fit future items.
    // If the post_residual is between 1 and 9 (the minimum possible item size), it is "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: If this is an existing bin, penalize the creation of new bins 
    // unless the fit is extremely tight (Best-Fit logic).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // If we open a new bin, we incur a cost based on current bin usage.
        // We only want to open a new one if existing bins are too full to be efficient.
        score += 20.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Favor bins that are already partially filled to pack them tighter.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Scarcity Penalty: If this is the last bin that can fit the item, 
    // we should prioritize using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // 5. Mean residual equilibrium: Avoid stranding items in bins that are significantly 
    // emptier than the average, which leads to fragmentation.
    if !is_new_bin && (bin_residual as f64) > (mean_residual * 1.5) {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin unless the current mean residual is very high,
    // indicating that existing bins are already too cluttered to fit future items.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            return 0.0;
        }
        // Heavily penalize new bin creation; only accept if mean_residual is extremely low
        score += 120.0 - (mean_residual * 1.5);
    } else {
        // 2. Best-Fit Decreasing logic: reward smaller post_residuals (tighter fits)
        // We use a non-linear penalty for large post_residuals to prioritize tight packing.
        score += (post_residual as f64).powf(1.1);

        // 3. Lookahead Matching: If the next item fits into the current post_residual, 
        // heavily reward this bin to keep the next item compact.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
            // Additional reward if the next item leaves very little space (near-perfect fit)
            if post_residual - next_item_size < 10 {
                score -= 20.0;
            }
        }

        // 4. Pressure management: If this is the ONLY bin that can fit the item,
        // we must prioritize it to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // 5. Global state adjustment: As the stream progresses, prioritize closing bins
        // (lower mean_residual) to maintain efficiency.
        let progress = step_index as f64 / total_items as f64;
        if post_residual < (mean_residual as u32) {
            score -= 10.0 * progress;
        }
    }

    score
}
